public with sharing class ContactTriggerHandler {

    public void beforeInsert(List<Contact> newContacts) {
        handleBefore(newContacts, true);
    }

    public void beforeUpdate(List<Contact> newContacts) {
        handleBefore(newContacts, false);
    }

    public void afterInsert(List<Contact> newContacts) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : newContacts) {
            if (c.AccountId != null && String.isNotBlank(c.Phone)) {
                accountIds.add(c.AccountId);
            }
        }
        if (accountIds.isEmpty()) {
            return;
        }

        // Single bulk query for all referenced accounts.
        Map<Id, Account> accountsById = new Map<Id, Account>(
            [SELECT Id, Phone FROM Account WHERE Id IN :accountIds]
        );

        Map<Id, Account> accountsToUpdate = new Map<Id, Account>();

        // Iterate in trigger order. The first contact for an account with a
        // blank Phone sets it on the queried Account instance, so subsequent
        // contacts for the same account see a non-blank Phone and are skipped.
        // This preserves the original first-contact-wins behaviour and ensures
        // each account is updated only once.
        for (Contact c : newContacts) {
            if (c.AccountId == null || String.isBlank(c.Phone)) {
                continue;
            }
            Account acc = accountsById.get(c.AccountId);
            if (acc == null) {
                continue;
            }
            if (String.isBlank(acc.Phone)) {
                acc.Phone = c.Phone;
                accountsToUpdate.put(acc.Id, acc);
            }
        }

        // Single DML statement for all accounts to update.
        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate.values();
        }
    }

    private void handleBefore(List<Contact> newContacts, Boolean isInsert) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : newContacts) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }
        if (accountIds.isEmpty()) {
            return;
        }

        // Single bulk query for all referenced accounts.
        Map<Id, Account> accountsById = new Map<Id, Account>(
            [SELECT Id, BillingCountry, AccountSource FROM Account WHERE Id IN :accountIds]
        );

        for (Contact c : newContacts) {
            if (c.AccountId == null) {
                continue;
            }
            Account acc = accountsById.get(c.AccountId);
            if (acc == null) {
                continue;
            }
            if (String.isBlank(c.MailingCountry)) {
                c.MailingCountry = acc.BillingCountry;
            }
            if (isInsert && String.isBlank(c.LeadSource)) {
                c.LeadSource = acc.AccountSource;
            }
        }
    }
}
