/**
 * Service for grouping Contacts by their email domain.
 */
public with sharing class ContactDomainService {

    /**
     * Returns the Contacts of the given Accounts grouped by the domain
     * part of their email address, lower-cased.
     *
     * Contacts without an email address, or with an email address that
     * has no domain part, are excluded. A null or empty set of Account
     * Ids returns an empty map.
     *
     * Record sharing is respected via the `with sharing` class keyword,
     * and object/field-level security is enforced via `WITH USER_MODE`.
     *
     * @param accountIds Ids of the Accounts whose Contacts should be grouped
     * @return Map from lower-cased email domain to the Contacts having that domain
     */
    public static Map<String, List<Contact>> groupByEmailDomain(Set<Id> accountIds) {
        Map<String, List<Contact>> contactsByDomain = new Map<String, List<Contact>>();

        if (accountIds == null || accountIds.isEmpty()) {
            return contactsByDomain;
        }

        // Exclude a possible null Id so that Contacts without an Account
        // can never be matched by `AccountId IN :accountIds`.
        Set<Id> validAccountIds = new Set<Id>();
        for (Id accountId : accountIds) {
            if (accountId != null) {
                validAccountIds.add(accountId);
            }
        }
        if (validAccountIds.isEmpty()) {
            return contactsByDomain;
        }

        for (Contact contactRecord : [
            SELECT Id, Email, AccountId
            FROM Contact
            WHERE AccountId IN :validAccountIds
            AND Email != null
            WITH USER_MODE
        ]) {
            if (String.isBlank(contactRecord.Email)) {
                continue;
            }

            String email = contactRecord.Email.trim();
            Integer atIndex = email.lastIndexOf('@');
            // Skip malformed addresses with no '@' or no domain part.
            if (atIndex < 0 || atIndex == email.length() - 1) {
                continue;
            }

            String domain = email.substring(atIndex + 1).trim().toLowerCase();
            if (String.isBlank(domain)) {
                continue;
            }

            List<Contact> domainContacts = contactsByDomain.get(domain);
            if (domainContacts == null) {
                domainContacts = new List<Contact>();
                contactsByDomain.put(domain, domainContacts);
            }
            domainContacts.add(contactRecord);
        }

        return contactsByDomain;
    }
}
