public with sharing class RecordSearchService {

    public class SearchException extends Exception {
    }

    public static List<SObject> search(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        try {
            if (maxRows == null || maxRows < 1 || maxRows > 200) {
                throw new SearchException('maxRows must be between 1 and 200.');
            }
            if (String.isBlank(objectApiName)) {
                throw new SearchException('Object does not exist: ' + objectApiName);
            }
            if (fields == null || fields.isEmpty()) {
                throw new SearchException('At least one field must be requested.');
            }

            // Resolve object case-insensitively to its canonical name/type.
            String objectKey = objectApiName.trim().toLowerCase();
            Schema.SObjectType objectType;
            Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();
            for (String apiName : globalDescribe.keySet()) {
                if (apiName != null && apiName.toLowerCase() == objectKey) {
                    objectType = globalDescribe.get(apiName);
                    break;
                }
            }
            if (objectType == null) {
                throw new SearchException('Object does not exist: ' + objectApiName);
            }

            Schema.DescribeSObjectResult objectDescribe = objectType.getDescribe();
            if (!objectDescribe.isAccessible()) {
                throw new SearchException(
                    'Running user cannot read object: ' + objectDescribe.getName()
                );
            }
            if (!objectDescribe.isQueryable()) {
                throw new SearchException(
                    'Object is not queryable: ' + objectDescribe.getName()
                );
            }

            // Index field describes by lower-cased canonical API name.
            Map<String, Schema.DescribeFieldResult> fieldsByLowerName =
                new Map<String, Schema.DescribeFieldResult>();
            for (Schema.SObjectField fieldToken : objectDescribe.fields.getMap().values()) {
                Schema.DescribeFieldResult fieldDescribe = fieldToken.getDescribe();
                fieldsByLowerName.put(fieldDescribe.getName().toLowerCase(), fieldDescribe);
            }

            // Validate requested fields, enforce FLS, de-duplicate (incl. Id).
            List<String> selectFieldNames = new List<String>{ 'Id' };
            Set<String> seenSelectFields = new Set<String>{ 'id' };
            for (String rawFieldName : fields) {
                Schema.DescribeFieldResult fieldDescribe =
                    resolveField(fieldsByLowerName, rawFieldName, objectDescribe.getName());
                if (!fieldDescribe.isAccessible()) {
                    throw new SearchException(
                        'Running user cannot read field: ' + fieldDescribe.getName()
                    );
                }
                String lowerName = fieldDescribe.getName().toLowerCase();
                if (!seenSelectFields.contains(lowerName)) {
                    seenSelectFields.add(lowerName);
                    selectFieldNames.add(fieldDescribe.getName());
                }
            }

            // Validate filter fields and build bind variables (never inline values).
            Map<String, Object> bindVariables = new Map<String, Object>();
            List<String> whereClauses = new List<String>();
            if (filters != null && !filters.isEmpty()) {
                Integer bindIndex = 0;
                for (String rawFieldName : filters.keySet()) {
                    Schema.DescribeFieldResult fieldDescribe =
                        resolveField(fieldsByLowerName, rawFieldName, objectDescribe.getName());
                    if (!fieldDescribe.isAccessible()) {
                        throw new SearchException(
                            'Running user cannot read field: ' + fieldDescribe.getName()
                        );
                    }
                    if (!fieldDescribe.isFilterable()) {
                        throw new SearchException(
                            'Field cannot be filtered: ' + fieldDescribe.getName()
                        );
                    }
                    String bindName = 'filterValue' + bindIndex;
                    bindIndex++;
                    whereClauses.add(fieldDescribe.getName() + ' = :' + bindName);
                    bindVariables.put(bindName, filters.get(rawFieldName));
                }
            }

            // Validate order-by field.
            String orderByCanonicalName;
            if (String.isNotBlank(orderByField)) {
                Schema.DescribeFieldResult fieldDescribe =
                    resolveField(fieldsByLowerName, orderByField, objectDescribe.getName());
                if (!fieldDescribe.isAccessible()) {
                    throw new SearchException(
                        'Running user cannot read field: ' + fieldDescribe.getName()
                    );
                }
                if (!fieldDescribe.isSortable()) {
                    throw new SearchException(
                        'Field cannot be sorted: ' + fieldDescribe.getName()
                    );
                }
                orderByCanonicalName = fieldDescribe.getName();
            }

            // Only canonical describe names and the validated integer limit are
            // concatenated; all filter values are passed as bind variables.
            String query =
                'SELECT ' + String.join(selectFieldNames, ', ') +
                ' FROM ' + objectDescribe.getName();
            if (!whereClauses.isEmpty()) {
                query += ' WHERE ' + String.join(whereClauses, ' AND ');
            }
            if (orderByCanonicalName != null) {
                query += ' ORDER BY ' + orderByCanonicalName + ' ASC';
            }
            query += ' LIMIT ' + maxRows;

            // USER_MODE enforces object/field-level security; `with sharing`
            // enforces record sharing.
            return Database.queryWithBinds(query, bindVariables, AccessLevel.USER_MODE);
        } catch (SearchException e) {
            throw e;
        } catch (Exception e) {
            throw new SearchException(e.getMessage());
        }
    }

    private static Schema.DescribeFieldResult resolveField(
        Map<String, Schema.DescribeFieldResult> fieldsByLowerName,
        String rawFieldName,
        String objectName
    ) {
        if (String.isBlank(rawFieldName)) {
            throw new SearchException('Field does not exist on ' + objectName + ': ' + rawFieldName);
        }
        Schema.DescribeFieldResult fieldDescribe =
            fieldsByLowerName.get(rawFieldName.trim().toLowerCase());
        if (fieldDescribe == null) {
            throw new SearchException('Field does not exist on ' + objectName + ': ' + rawFieldName);
        }
        return fieldDescribe;
    }
}
