public with sharing class ContactLookupAction {

    public class Request {
        @InvocableVariable(required=true label='Email' description='Email address to search for. Matching is case-insensitive and leading/trailing spaces are ignored.')
        public String email;
    }

    public class Result {
        @InvocableVariable(label='Contact Id' description='Id of the matching Contact, or null if no Contact was found.')
        public Id contactId;

        @InvocableVariable(label='Found' description='True if a matching Contact was found; otherwise false.')
        public Boolean found;

        public Result() {
            this.contactId = null;
            this.found = false;
        }

        public Result(Id contactId, Boolean found) {
            this.contactId = contactId;
            this.found = found;
        }
    }

    @InvocableMethod(label='Find Contact by Email' description='Finds an existing Contact by email address. Matching is case-insensitive and ignores leading/trailing spaces. If multiple Contacts match, the earliest created Contact is returned.')
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();

        if (requests == null || requests.isEmpty()) {
            return results;
        }

        List<String> normalizedByIndex = new List<String>();
        Set<String> emailsToQuery = new Set<String>();

        for (Request request : requests) {
            String normalizedEmail = null;

            if (request != null && String.isNotBlank(request.email)) {
                normalizedEmail = request.email.trim().toLowerCase();
                emailsToQuery.add(normalizedEmail);
            }

            normalizedByIndex.add(normalizedEmail);
        }

        Map<String, Id> earliestContactIdByEmail = new Map<String, Id>();

        if (!emailsToQuery.isEmpty()) {
            // Single bulkified query for the whole batch. SOQL string
            // comparison is case-insensitive, so querying with the
            // lower-cased values matches Contacts stored in any case.
            // Ordering by CreatedDate ensures the first record seen for
            // each email is the earliest created one.
            for (Contact contact : [
                SELECT Id, Email
                FROM Contact
                WHERE Email IN :emailsToQuery
                ORDER BY CreatedDate ASC, Id ASC
            ]) {
                if (String.isBlank(contact.Email)) {
                    continue;
                }

                String key = contact.Email.trim().toLowerCase();

                if (!earliestContactIdByEmail.containsKey(key)) {
                    earliestContactIdByEmail.put(key, contact.Id);
                }
            }
        }

        for (String normalizedEmail : normalizedByIndex) {
            Result result = new Result();

            if (normalizedEmail != null && earliestContactIdByEmail.containsKey(normalizedEmail)) {
                result.contactId = earliestContactIdByEmail.get(normalizedEmail);
                result.found = true;
            } else {
                result.contactId = null;
                result.found = false;
            }

            results.add(result);
        }

        return results;
    }
}
