public class OrderPayloadParser {

    public class PayloadException extends Exception {
    }

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
    }

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public static Order parse(String body) {
        if (String.isBlank(body)) {
            throw new PayloadException('Payload body is null or blank.');
        }

        try {
            Object parsed = JSON.deserializeUntyped(body);

            if (parsed == null || !(parsed instanceof Map<String, Object>)) {
                throw new PayloadException('Payload must be a JSON object.');
            }
            Map<String, Object> root = (Map<String, Object>) parsed;

            // number (required, non-blank)
            Object numberValue = root.get('number');
            if (numberValue == null || !(numberValue instanceof String)
                    || String.isBlank((String) numberValue)) {
                throw new PayloadException('Missing or blank number.');
            }

            Order order = new Order();
            order.orderNumber = (String) numberValue;

            // date (optional, ISO yyyy-MM-dd)
            Object dateValue = root.get('date');
            if (dateValue == null) {
                order.orderDate = null;
            } else {
                if (!(dateValue instanceof String)
                        || String.isBlank((String) dateValue)) {
                    throw new PayloadException('Invalid date.');
                }
                String dateString = ((String) dateValue).trim();
                if (!dateString.matches('\\d{4}-\\d{2}-\\d{2}')) {
                    throw new PayloadException('Invalid date: ' + dateString);
                }
                try {
                    order.orderDate = Date.valueOf(dateString);
                } catch (Exception e) {
                    throw new PayloadException('Invalid date: ' + dateString);
                }
            }

            // currency (optional)
            Object currencyValue = root.get('currency');
            if (currencyValue == null) {
                order.currencyCode = null;
            } else if (currencyValue instanceof String) {
                order.currencyCode = (String) currencyValue;
            } else {
                throw new PayloadException('Invalid currency.');
            }

            // customer (optional)
            order.customerEmail = null;
            Object customerValue = root.get('customer');
            if (customerValue != null) {
                if (!(customerValue instanceof Map<String, Object>)) {
                    throw new PayloadException('Invalid customer.');
                }
                Map<String, Object> customer =
                    (Map<String, Object>) customerValue;
                Object emailValue = customer.get('email');
                if (emailValue == null) {
                    order.customerEmail = null;
                } else if (emailValue instanceof String) {
                    order.customerEmail = (String) emailValue;
                } else {
                    throw new PayloadException('Invalid customer.email.');
                }
            }

            // lines (optional, defaults to empty list)
            order.lines = new List<Line>();
            Decimal total = 0;

            Object linesValue = root.get('lines');
            if (linesValue != null) {
                if (!(linesValue instanceof List<Object>)) {
                    throw new PayloadException('Invalid lines.');
                }
                for (Object lineValue : (List<Object>) linesValue) {
                    if (lineValue == null
                            || !(lineValue instanceof Map<String, Object>)) {
                        throw new PayloadException('Invalid line.');
                    }
                    Map<String, Object> lineMap =
                        (Map<String, Object>) lineValue;

                    Line line = new Line();

                    // sku (required)
                    Object skuValue = lineMap.get('sku');
                    if (skuValue == null || !(skuValue instanceof String)
                            || String.isBlank((String) skuValue)) {
                        throw new PayloadException('Missing sku.');
                    }
                    line.sku = (String) skuValue;

                    // quantity (required, positive integer)
                    Object quantityValue = lineMap.get('quantity');
                    if (quantityValue == null) {
                        throw new PayloadException('Missing quantity.');
                    }
                    Integer quantity = toInteger(quantityValue, 'quantity');
                    if (quantity == null || quantity <= 0) {
                        throw new PayloadException(
                            'Missing or non-positive quantity.');
                    }
                    line.quantity = quantity;

                    // unitPrice (required, non-negative)
                    Object unitPriceValue = lineMap.get('unitPrice');
                    if (unitPriceValue == null) {
                        throw new PayloadException('Missing unitPrice.');
                    }
                    Decimal unitPrice = toDecimal(unitPriceValue, 'unitPrice');
                    if (unitPrice == null || unitPrice < 0) {
                        throw new PayloadException(
                            'Missing or negative unitPrice.');
                    }
                    line.unitPrice = unitPrice;

                    // discount (optional, 0 to 1, defaults to 0)
                    Object discountValue = lineMap.get('discount');
                    Decimal discount = 0;
                    if (discountValue != null) {
                        discount = toDecimal(discountValue, 'discount');
                        if (discount == null || discount < 0 || discount > 1) {
                            throw new PayloadException('Invalid discount.');
                        }
                    }
                    line.discount = discount;

                    Decimal lineTotal = (Decimal.valueOf(quantity)
                        * unitPrice
                        * (1 - discount))
                        .setScale(2, RoundingMode.HALF_UP);
                    line.lineTotal = lineTotal;
                    total += lineTotal;

                    order.lines.add(line);
                }
            }

            order.total = total;
            return order;
        } catch (PayloadException e) {
            throw e;
        } catch (Exception e) {
            throw new PayloadException('Invalid payload: ' + e.getMessage());
        }
    }

    public static String toAcknowledgement(Order order) {
        if (order == null) {
            throw new PayloadException('Order is null.');
        }
        try {
            Integer lineCount = order.lines == null ? 0 : order.lines.size();
            Decimal total = order.total == null ? 0 : order.total;

            Map<String, Object> acknowledgement = new Map<String, Object>{
                'number' => order.orderNumber,
                'status' => 'RECEIVED',
                'lineCount' => lineCount,
                'total' => total
            };
            return JSON.serialize(acknowledgement);
        } catch (PayloadException e) {
            throw e;
        } catch (Exception e) {
            throw new PayloadException(
                'Invalid order: ' + e.getMessage());
        }
    }

    private static Decimal toDecimal(Object value, String fieldName) {
        if (value instanceof Decimal) {
            return (Decimal) value;
        }
        if (value instanceof Integer) {
            return Decimal.valueOf((Integer) value);
        }
        if (value instanceof Long) {
            return Decimal.valueOf((Long) value);
        }
        if (value instanceof Double) {
            return Decimal.valueOf((Double) value);
        }
        throw new PayloadException('Invalid ' + fieldName + '.');
    }

    private static Integer toInteger(Object value, String fieldName) {
        Decimal decimalValue = toDecimal(value, fieldName);
        if (decimalValue.setScale(0, RoundingMode.DOWN) != decimalValue) {
            throw new PayloadException('Invalid ' + fieldName + '.');
        }
        try {
            return decimalValue.intValue();
        } catch (Exception e) {
            throw new PayloadException('Invalid ' + fieldName + '.');
        }
    }
}
