@isTest
private class ShippingCostCalculatorTest {

    private static void assertQuote(
        Decimal weightKg,
        String zone,
        Boolean express,
        Decimal orderValue,
        Decimal expected
    ) {
        Decimal actual = ShippingCostCalculator.quote(weightKg, zone, express, orderValue);
        Assert.areEqual(
            expected,
            actual,
            'weightKg=' + weightKg + ', zone=' + zone + ', express=' + express +
            ', orderValue=' + orderValue + ' expected ' + expected + ' but got ' + actual
        );
        Assert.isTrue(
            expected == actual,
            'Exact decimal mismatch for weightKg=' + weightKg + ', zone=' + zone
        );
    }

    private static void assertShippingException(
        Decimal weightKg,
        String zone,
        Boolean express,
        Decimal orderValue
    ) {
        try {
            Decimal result = ShippingCostCalculator.quote(weightKg, zone, express, orderValue);
            Assert.fail(
                'Expected ShippingException for weightKg=' + weightKg + ', zone=' + zone +
                ', express=' + express + ', orderValue=' + orderValue + ' but got price ' + result
            );
        } catch (ShippingCostCalculator.ShippingException expectedException) {
            Assert.isNotNull(expectedException, 'ShippingException should be thrown');
        }
    }

    // ------------------------------------------------------------------
    // Weight validation
    // ------------------------------------------------------------------

    @isTest
    static void nullWeight_throws() {
        assertShippingException(null, 'DOMESTIC', false, 0);
        assertShippingException(null, 'EU', true, 0);
        assertShippingException(null, 'WORLD', null, null);
    }

