public with sharing class PicklistService {

    public class Option {
        public String value;
        public String label;
        public Boolean isDefault;

        public Option() {
            this.isDefault = false;
        }

        public Option(String value, String label, Boolean isDefault) {
            this.value = value;
            this.label = label;
            this.isDefault = (isDefault == true);
        }
    }

    public class PicklistServiceException extends Exception {
    }

    public static List<PicklistService.Option> activeOptions(String objectApiName, String fieldApiName) {
        try {
            if (String.isBlank(objectApiName)) {
                throw new PicklistServiceException('Object API name must not be null or blank.');
            }
            if (String.isBlank(fieldApiName)) {
                throw new PicklistServiceException('Field API name must not be null or blank.');
            }

            String objectName = objectApiName.trim();
            String fieldName = fieldApiName.trim();

            // Resolve object case-insensitively.
            Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();
            if (globalDescribe == null || globalDescribe.isEmpty()) {
                throw new PicklistServiceException('Object does not exist: ' + objectName);
            }

            Schema.SObjectType sObjectType = globalDescribe.get(objectName);
            if (sObjectType == null) {
                for (String key : globalDescribe.keySet()) {
                    if (key != null && key.equalsIgnoreCase(objectName)) {
                        sObjectType = globalDescribe.get(key);
                        break;
                    }
                }
            }
            if (sObjectType == null) {
                throw new PicklistServiceException('Object does not exist: ' + objectName);
            }

            // Resolve field case-insensitively.
            Map<String, Schema.SObjectField> fieldMap = sObjectType.getDescribe().fields.getMap();
            if (fieldMap == null || fieldMap.isEmpty()) {
                throw new PicklistServiceException(
                    'Field does not exist on object ' + objectName + ': ' + fieldName
                );
            }

            Schema.SObjectField fieldToken = fieldMap.get(fieldName);
            if (fieldToken == null) {
                for (String key : fieldMap.keySet()) {
                    if (key != null && key.equalsIgnoreCase(fieldName)) {
                        fieldToken = fieldMap.get(key);
                        break;
                    }
                }
            }
            if (fieldToken == null) {
                throw new PicklistServiceException(
                    'Field does not exist on object ' + objectName + ': ' + fieldName
                );
            }

            Schema.DescribeFieldResult fieldDescribe = fieldToken.getDescribe();
            if (fieldDescribe == null) {
                throw new PicklistServiceException(
                    'Field does not exist on object ' + objectName + ': ' + fieldName
                );
            }

            Schema.DisplayType fieldType = fieldDescribe.getType();
            if (fieldType != Schema.DisplayType.Picklist &&
                fieldType != Schema.DisplayType.Multipicklist) {
                throw new PicklistServiceException(
                    'Field is not a picklist or multi-select picklist: ' +
                    objectName + '.' + fieldName
                );
            }

            List<PicklistService.Option> result = new List<PicklistService.Option>();
            List<Schema.PicklistEntry> picklistValues = fieldDescribe.getPicklistValues();
            if (picklistValues == null) {
                return result;
            }

            for (Schema.PicklistEntry entry : picklistValues) {
                if (entry == null) {
                    continue;
                }
                if (!entry.isActive()) {
                    continue;
                }
                PicklistService.Option option = new PicklistService.Option();
                option.value = entry.getValue();
                option.label = entry.getLabel();
                option.isDefault = entry.isDefaultValue();
                result.add(option);
            }

            return result;
        } catch (PicklistServiceException e) {
            throw e;
        } catch (Exception e) {
            throw new PicklistServiceException(
                'Unable to retrieve picklist options for ' +
                String.valueOf(objectApiName) + '.' + String.valueOf(fieldApiName) +
                ': ' + e.getMessage()
            );
        }
    }
}
