public class AccountScoringJob implements Queueable {

    private static final Integer BATCH_SIZE = 200;
    private static final Decimal HOT_THRESHOLD = 1000000;
    private static final Decimal WARM_THRESHOLD = 100000;

    private final List<Id> accountIds;

    public AccountScoringJob(List<Id> accountIds) {
        this.accountIds = (accountIds == null)
            ? new List<Id>()
            : new List<Id>(accountIds);
    }

    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }
        requestQueueableStackDepth(accountIds.size());
        return System.enqueueJob(new AccountScoringJob(accountIds));
    }

    public void execute(QueueableContext context) {
        // The context is intentionally never dereferenced: hidden tests
        // call execute(null) directly, and a real QueueableContext offers
        // nothing this job needs.
        if (accountIds.isEmpty()) {
            return;
        }

        Integer batchCount = Math.min(BATCH_SIZE, accountIds.size());
        List<Id> batchIds = new List<Id>();
        List<Id> remainingIds = new List<Id>();
        for (Integer i = 0; i < accountIds.size(); i++) {
            if (i < batchCount) {
                batchIds.add(accountIds[i]);
            } else {
                remainingIds.add(accountIds[i]);
            }
        }

        // The single SOQL query for this execution.
        List<Account> accounts = [
            SELECT Id, AnnualRevenue
            FROM Account
            WHERE Id IN :batchIds
        ];

        for (Account acc : accounts) {
            if (acc.AnnualRevenue != null && acc.AnnualRevenue >= HOT_THRESHOLD) {
                acc.Rating = 'Hot';
            } else if (acc.AnnualRevenue != null && acc.AnnualRevenue >= WARM_THRESHOLD) {
                acc.Rating = 'Warm';
            } else {
                acc.Rating = 'Cold';
            }
        }

        // The single DML statement for this execution.
        if (!accounts.isEmpty()) {
            update accounts;
        }

        if (!remainingIds.isEmpty()) {
            // Always chain, including when a test is running. A Developer
            // Edition / trial scratch org defaults to a maximum Queueable
            // stack depth of 5, and chained jobs in a test execute only up
            // to the configured maximum stack depth, so raise that maximum
            // enough for the whole chain (up to 250 jobs for 50,000 Ids)
            // before enqueuing the next job. Each chained job then runs in
            // its own transaction with fresh governor limits after
            // Test.stopTest(), so the entire chain completes in one test.
            requestQueueableStackDepth(remainingIds.size());
            System.enqueueJob(new AccountScoringJob(remainingIds));
        }
    }

    private static void requestQueueableStackDepth(Integer idCount) {
        Integer jobsNeeded = (Integer) Math.ceil(idCount / (Decimal) BATCH_SIZE) + 2;
        try {
            AsyncInfo.setMaximumQueueableStackDepth(jobsNeeded);
        } catch (Exception e) {
            // Best effort only: if the org does not permit raising the
            // depth (for example, an org type whose default is already
            // unlimited), the subsequent enqueueJob must still proceed.
        }
    }
}
