public class ErpSyncFinalizer implements Finalizer {
    private final Set<Id> accountIds;
    private final Integer attempt;

    public ErpSyncFinalizer(Set<Id> accountIds, Integer attempt) {
        this.accountIds = accountIds == null ? new Set<Id>() : new Set<Id>(accountIds);
        this.attempt = attempt == null ? 1 : attempt;
    }

    public void execute(FinalizerContext ctx) {
        Boolean succeeded = ctx.getResult() == ParentJobResult.SUCCESS;

        FB_Job_Log__c log = new FB_Job_Log__c(
            Job_Name__c = 'ErpAccountSyncJob',
            Attempt__c = attempt,
            Status__c = succeeded ? 'Success' : 'Failed'
        );

        if (!succeeded) {
            Exception ex = ctx.getException();
            if (ex != null && ex.getMessage() != null) {
                String message = ex.getMessage();
                log.Error__c = message.length() > 255 ? message.substring(0, 255) : message;
            }
        }

        insert log;

        if (!succeeded && attempt < 3) {
            System.enqueueJob(new ErpAccountSyncJob(accountIds, attempt + 1));
        }
    }
}
