public with sharing class OpportunityPipelineHandler {

    public static void afterInsert(List<Opportunity> newOpportunities) {
        Set<Id> accountIds = new Set<Id>();
        for (Opportunity opp : newOpportunities) {
            if (opp.AccountId != null) {
                accountIds.add(opp.AccountId);
            }
        }
        recalculate(accountIds);
    }

    public static void afterUpdate(List<Opportunity> newOpportunities, Map<Id, Opportunity> oldMap) {
        Set<Id> accountIds = new Set<Id>();
        for (Opportunity opp : newOpportunities) {
            Opportunity oldOpp = oldMap.get(opp.Id);
            // Only fields that can affect the open-pipeline totals matter.
            // In particular, the legacy AccountTrigger updates
            // FB_Account_Rating__c on open opportunities whenever an
            // Account is updated. Ignoring that (and any other
            // irrelevant) change breaks the Account -> Opportunity ->
            // Account recursion cycle without suppressing genuine
            // later DML in the same transaction (no static guard flag).
            Boolean relevantChange =
                opp.Amount != oldOpp.Amount ||
                opp.AccountId != oldOpp.AccountId ||
                opp.IsClosed != oldOpp.IsClosed ||
                opp.StageName != oldOpp.StageName;

            if (relevantChange) {
                if (opp.AccountId != null) {
                    accountIds.add(opp.AccountId);
                }
                if (oldOpp.AccountId != null) {
                    accountIds.add(oldOpp.AccountId);
                }
            }
        }
        recalculate(accountIds);
    }

    public static void afterDelete(List<Opportunity> oldOpportunities) {
        Set<Id> accountIds = new Set<Id>();
        for (Opportunity opp : oldOpportunities) {
            if (opp.AccountId != null) {
                accountIds.add(opp.AccountId);
            }
        }
        recalculate(accountIds);
    }

    public static void afterUndelete(List<Opportunity> newOpportunities) {
        Set<Id> accountIds = new Set<Id>();
        for (Opportunity opp : newOpportunities) {
            if (opp.AccountId != null) {
                accountIds.add(opp.AccountId);
            }
        }
        recalculate(accountIds);
    }

    /**
     * Recomputes FB_Open_Pipeline__c / FB_Open_Opportunities__c from the
     * database for every affected account, so the result is correct after
     * every DML statement, including repeated DML in one transaction.
     * Bulk-safe: 2 SOQL queries and at most 1 DML statement per invocation.
     */
    private static void recalculate(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        Map<Id, Decimal> pipelineByAccountId = new Map<Id, Decimal>();
        Map<Id, Decimal> countByAccountId = new Map<Id, Decimal>();

        // SUM(Amount) ignores null Amounts (blank counts as 0 for the sum);
        // COUNT(Id) counts every open opportunity, including blank-Amount ones.
        for (AggregateResult result : [
            SELECT AccountId, SUM(Amount) totalAmount, COUNT(Id) totalCount
            FROM Opportunity
            WHERE AccountId IN :accountIds
            AND IsClosed = false
            GROUP BY AccountId
        ]) {
            Id accountId = (Id) result.get('AccountId');
            Decimal totalAmount = (Decimal) result.get('totalAmount');
            Integer totalCount = (Integer) result.get('totalCount');
            pipelineByAccountId.put(accountId, totalAmount == null ? 0 : totalAmount);
            countByAccountId.put(accountId, totalCount == null ? 0 : Decimal.valueOf(totalCount));
        }

        List<Account> accountsToUpdate = new List<Account>();
        for (Account acc : [
            SELECT Id, FB_Open_Pipeline__c, FB_Open_Opportunities__c
            FROM Account
            WHERE Id IN :accountIds
        ]) {
            // Accounts with no remaining open opportunities get 0 / 0, not blank.
            Decimal newPipeline = pipelineByAccountId.containsKey(acc.Id)
                ? pipelineByAccountId.get(acc.Id)
                : 0;
            Decimal newCount = countByAccountId.containsKey(acc.Id)
                ? countByAccountId.get(acc.Id)
                : 0;

            // Only update when the totals actually changed. This avoids
            // firing the legacy AccountTrigger (and its Opportunity update)
            // unnecessarily and helps terminate the recursion cycle.
            if (acc.FB_Open_Pipeline__c != newPipeline || acc.FB_Open_Opportunities__c != newCount) {
                accountsToUpdate.add(new Account(
                    Id = acc.Id,
                    FB_Open_Pipeline__c = newPipeline,
                    FB_Open_Opportunities__c = newCount
                ));
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
