public without sharing class LogPurgeJob implements Schedulable {

    public LogPurgeJob() {
    }

    public void execute(SchedulableContext context) {
        Datetime standardCutoff = System.now().addDays(-30);
        Datetime errorCutoff = System.now().addDays(-180);

        List<FB_Integration_Log__c> logsToDelete = [
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE CreatedDate < :errorCutoff
               OR (
                   CreatedDate < :standardCutoff
                   AND (Level__c = null OR Level__c != 'ERROR')
               )
            ORDER BY CreatedDate ASC
            LIMIT 10000
        ];

        if (!logsToDelete.isEmpty()) {
            Database.delete(logsToDelete, false);
        }
    }

    public static Id scheduleNightly() {
        return System.schedule(
            'Log purge (nightly)',
            '0 0 2 * * ?',
            new LogPurgeJob()
        );
    }
}
