public class Opportunities extends fflib_SObjectDomain {

    private static final String STAGE_CLOSED_WON = 'Closed Won';

    public Opportunities(List<SObject> sObjectList) {
        super(sObjectList);
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> sObjectList) {
            return new Opportunities(sObjectList);
        }
    }

    public override void onAfterInsert() {
        Set<Id> qualifyingIds = new Set<Id>();

        for (SObject record : Records) {
            Opportunity opportunity = (Opportunity) record;
            if (opportunity.StageName == STAGE_CLOSED_WON && opportunity.Id != null) {
                qualifyingIds.add(opportunity.Id);
            }
        }

        startFulfilment(qualifyingIds);
    }

    public override void onAfterUpdate(Map<Id, SObject> existingRecords) {
        Set<Id> qualifyingIds = new Set<Id>();

        for (SObject record : Records) {
            Opportunity opportunity = (Opportunity) record;
            Opportunity existingOpportunity = existingRecords != null
                ? (Opportunity) existingRecords.get(opportunity.Id)
                : null;

            if (
                opportunity.StageName == STAGE_CLOSED_WON &&
                (existingOpportunity == null ||
                    existingOpportunity.StageName != STAGE_CLOSED_WON) &&
                opportunity.Id != null
            ) {
                qualifyingIds.add(opportunity.Id);
            }
        }

        startFulfilment(qualifyingIds);
    }

    private void startFulfilment(Set<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return;
        }

        IOpportunityFulfilmentService fulfilmentService =
            (IOpportunityFulfilmentService) Application.Service.newInstance(
                IOpportunityFulfilmentService.class
            );

        fulfilmentService.startFulfilment(opportunityIds);
    }
}
