```apex
/**
 * Cleans Contact phone numbers for the dialer, which accepts only digits
 * and a single leading '+'.
 *
 * Deviations from the approach as originally described, and why:
 *
 * 1. Only contacts whose Phone actually changes are added to the update
 *    list. Updating already-clean numbers would waste DML, could run
 *    validation rules / automation needlessly, and could cause a clean
 *    record to be reported as a failure for reasons unrelated to this
 *    cleanup.
 *
 * 2. A '+' is preserved only in the leading position. Simply deleting
 *    every character that is not a digit or '+' would leave values such
 *    as '44+20' or '++44' untouched in the middle/at the front, which
 *    the dialer (digits plus a *leading* plus) would still reject.
 *    Non-leading pluses are therefore removed; a leading plus is kept.
 *    For all ordinary input this matches the specified behaviour, e.g.
 *    '+44 (20) 7946-0018' becomes '+442079460018'.
 *
 * 3. The Id recorded for a failed save is taken from the record at the
 *    same index in the update list, not from SaveResult.getId().
 *    SaveResult.getId() is null when the operation failed, so using it
 *    would collapse every failure onto a single null key. Save results
 *    are returned in the same order as the records submitted, so index
 *    correlation is the reliable way to attribute failures.
 *
 * 4. Null/empty input is short-circuited and no DML is performed when
 *    nothing needs changing, avoiding useless SOQL/DML calls.
 *
 * 5. Security: the class runs `with sharing` and both the query and the
 *    DML use USER_MODE, so the current user's record visibility, CRUD
 *    and field-level security are respected instead of silently running
 *    in system mode. A lack of access surfaces as a normal per-record
 *    failure in the returned map rather than an exception.
 *
 * The core of the requested approach is unchanged: one bulkified query,
 * one Database.update(list, false) so one bad record cannot block the
 * rest, and a map of record Id -> first error message for the failures
 * (empty when everything saved).
 */
public with sharing class ContactPhoneCleanup {

    public static Map<Id, String> normalizePhones(List<Id> contactIds) {
        Map<Id, String> failuresByContactId = new Map<Id, String>();

        if (contactIds == null || contactIds.isEmpty()) {
            return failuresByContactId;
        }

        // De-duplicate (query results would be de-duplicated anyway) and
        // drop nulls so the SOQL bind is clean.
        Set<Id> uniqueContactIds = new Set<Id>();
        for (Id contactId : contactIds) {
            if (contactId != null) {
                uniqueContactIds.add(contactId);
            }
        }
        if (uniqueContactIds.isEmpty()) {
            return failuresByContactId;
        }

        List<Contact> contactsToUpdate = new List<Contact>();

        for (Contact c : [
            SELECT Id, Phone
            FROM Contact
            WHERE Id IN :uniqueContactIds
            AND Phone != null
            WITH USER_MODE
        ]) {
            if (String.isBlank(c.Phone)) {
                continue;
            }

            // Remove everything that is not a digit or '+'.
            String stripped = c.Phone.replaceAll('[^0-9+]', '');

            // Keep '+' only as a single leading character (deviation 2).
            Boolean hasLeadingPlus = stripped.startsWith('+');
            String digits = stripped.replace('+', '');
            String normalized = String.isBlank(digits)
                ? ''
                : (hasLeadingPlus ? '+' + digits : digits);

            // Contacts without a (changed) phone are left out entirely
            // (deviation 1).
            if (normalized == c.Phone) {
                continue;
            }

            c.Phone = normalized;
            contactsToUpdate.add(c);
        }

        if (contactsToUpdate.isEmpty()) {
            return failuresByContactId;
        }

        // Single partial-success DML call, as requested: one record
        // failing validation does not block the others.
        List<Database.SaveResult> results = Database.update(
            contactsToUpdate,
            false,
            AccessLevel.USER_MODE
        );

        // Results align by index with contactsToUpdate (deviation 3).
        for (Integer i = 0; i < results.size(); i++) {
            Database.SaveResult result = results[i];
            if (!result.isSuccess()) {
                String firstErrorMessage = result.getErrors().isEmpty()
                    ? 'Unknown error'
                    : result.getErrors()[0].getMessage();
                failuresByContactId.put(contactsToUpdate[i].Id, firstErrorMessage);
            }
        }

        return failuresByContactId;
    }
}
