```apex
/**
 * Totals for the weekly pipeline call.
 *
 * Implementation note — why this does NOT loop over the stages issuing one
 * query per stage, even though there are currently only four:
 *  - "No SOQL in loops" exists to protect the per-transaction governor limit
 *    (100 SOQL queries). Four queries is fine only if this method is called
 *    once; called from a trigger, a batch, or alongside other logic, those
 *    four queries multiply and can push the transaction over the limit.
 *  - A single aggregate query with GROUP BY does the same work in one query
 *    regardless of how often the method is called or how many stages are
 *    ever added, lets the database do the grouping, and is no harder to read.
 * So: initialise every stage to 0, run one grouped query, overlay the sums.
 */
public with sharing class PipelineSummary {

    private static final List<String> STAGES = new List<String>{
        'Prospecting',
        'Qualification',
        'Proposal/Price Quote',
        'Negotiation/Review'
    };

    public static Map<String, Decimal> totalsByStage(Date fromDate, Date toDate) {
        // Pre-seed all four keys so a stage with no matching data maps to 0,
        // never null, and the returned map always has exactly four entries.
        Map<String, Decimal> totals = new Map<String, Decimal>();
        for (String stage : STAGES) {
            totals.put(stage, 0);
        }

        // No valid range means no opportunities can match; return the zeroes
        // without spending a query.
        if (fromDate == null || toDate == null || fromDate > toDate) {
            return totals;
        }

        // One bulk-safe, sharing/FLS-respecting query for all four stages.
        // SUM ignores null Amounts, so amount-less opportunities add nothing.
        // WITH USER_MODE enforces object/field-level security for the caller.
        for (AggregateResult ar : [
            SELECT StageName, SUM(Amount) total
            FROM Opportunity
            WHERE StageName IN :STAGES
              AND CloseDate >= :fromDate
              AND CloseDate <= :toDate
            WITH USER_MODE
            GROUP BY StageName
        ]) {
            String stage = (String) ar.get('StageName');
            Object sumValue = ar.get('total');
            // A group consisting solely of null Amounts yields a null SUM.
            Decimal sumAmount = sumValue == null ? 0 : (Decimal) sumValue;
            if (totals.containsKey(stage)) {
                totals.put(stage, sumAmount);
            }
        }

        return totals;
    }
}
