/**
 * Pushes newly created Accounts to the ERP as customers.
 *
 * Runs as a Queueable because callouts cannot be made directly from a
 * trigger. All accounts from the trigger chunk are sent in a single
 * request (the ERP accepts 1-200 customers per request), rather than
 * one request per account, which would breach the per-transaction
 * callout limit for batches of up to 200 records.
 */
public with sharing class ErpCustomerSync implements Queueable, Database.AllowsCallouts {

    private static final Integer MAX_CUSTOMERS_PER_REQUEST = 200;

    private final List<Customer> customers;

    public ErpCustomerSync(List<Customer> customers) {
        this.customers = customers;
    }

    /**
     * Called from the after-insert trigger. Captures only the fields the
     * ERP needs, in a lightweight serializable form, and enqueues one
     * asynchronous job for the whole trigger chunk.
     */
    public static void enqueue(List<Account> accounts) {
        if (accounts == null || accounts.isEmpty()) {
            return;
        }

        List<Customer> payload = new List<Customer>();
        for (Account acc : accounts) {
            payload.add(new Customer(
                // String.valueOf(Id) yields the 18-character Id.
                String.valueOf(acc.Id),
                acc.Name,
                String.isBlank(acc.BillingCountry) ? null : acc.BillingCountry
            ));
        }

        System.enqueueJob(new ErpCustomerSync(payload));
    }

    public void execute(QueueableContext context) {
        if (customers == null || customers.isEmpty()) {
            return;
        }

        for (Integer start = 0; start < customers.size(); start += MAX_CUSTOMERS_PER_REQUEST) {
            Integer endIndex = Math.min(start + MAX_CUSTOMERS_PER_REQUEST, customers.size());
            List<Customer> batch = new List<Customer>();
            for (Integer i = start; i < endIndex; i++) {
                batch.add(customers[i]);
            }
            send(batch);
        }
    }

    private static void send(List<Customer> batch) {
        HttpRequest request = new HttpRequest();
        request.setEndpoint('callout:ERP/api/customers');
        request.setMethod('POST');
        request.setHeader('Content-Type', 'application/json');
        // Default JSON serialization includes nulls, so a blank
        // BillingCountry is sent as "country": null as required.
        request.setBody(JSON.serialize(batch));

        // ERP answers 202 Accepted. Error handling and retries are
        // explicitly out of scope for this ticket, so the response
        // is not acted on here.
        HttpResponse response = new Http().send(request);
    }

    /**
     * Serializable DTO matching the ERP payload contract exactly.
     * Field names are serialized as declared.
     */
    private class Customer {
        public String salesforceId;
        public String name;
        public String country;

        public Customer(String salesforceId, String name, String country) {
            this.salesforceId = salesforceId;
            this.name = name;
            this.country = country;
        }
    }
}
