```apex
trigger OpportunityTrigger on Opportunity(
    after insert,
    after update,
    after delete,
    after undelete
) {
    Set<Id> accountIds = new Set<Id>();

    if (Trigger.isDelete) {
        // Trigger.new is unavailable; the old account may lose its last
        // open Opportunity and must be recalculated.
        for (Opportunity opp : Trigger.old) {
            if (opp.AccountId != null) {
                accountIds.add(opp.AccountId);
            }
        }
    } else if (Trigger.isUpdate) {
        for (Opportunity opp : Trigger.new) {
            Opportunity oldOpp = Trigger.oldMap.get(opp.Id);

            Boolean relevantChange =
                opp.StageName != oldOpp.StageName ||
                opp.Amount != oldOpp.Amount ||
                opp.AccountId != oldOpp.AccountId;

            if (!relevantChange) {
                continue;
            }

            // Recalculate the current account, and also the previous one
            // if the Opportunity was moved to a different account.
            if (opp.AccountId != null) {
                accountIds.add(opp.AccountId);
            }
            if (oldOpp.AccountId != null && oldOpp.AccountId != opp.AccountId) {
                accountIds.add(oldOpp.AccountId);
            }
        }
    } else {
        // after insert / after undelete
        for (Opportunity opp : Trigger.new) {
            if (opp.AccountId != null) {
                accountIds.add(opp.AccountId);
            }
        }
    }

    if (accountIds.isEmpty()) {
        return;
    }

    // Exactly one asynchronous invocation per transaction, regardless of
    // batch size. A @future method cannot be called from a future, batch
    // or queueable context, so fall back to running inline there rather
    // than failing the Opportunity save.
    if (System.isFuture() || System.isBatch() || System.isQueueable()) {
        AccountRatingService.recalculateSynchronously(accountIds);
    } else {
        AccountRatingService.recalculate(accountIds);
    }
}
