/**
 * Keeps Account.Rating in sync with the account's open pipeline:
 *   Hot  - at least one open Opportunity with Amount >= 100,000
 *   Warm - has open Opportunities, but none that large
 *   Cold - no open Opportunities
 *
 * Bulk-safe: a single aggregate query and a single DML statement for any
 * number of accounts, and only accounts whose Rating actually changes
 * are updated.
 */
public with sharing class AccountRatingService {
    private static final Decimal HOT_THRESHOLD = 100000;

    /**
     * Asynchronous entry point. Set<Id> is used because @future methods
     * only accept primitive types and collections of primitive types, and
     * because one call must serve an entire trigger batch (max 50 @future
     * calls per transaction).
     */
    @future
    public static void recalculate(Set<Id> accountIds) {
        performRecalculation(accountIds);
    }

    /**
     * Synchronous entry point for use when already executing in an
     * asynchronous context, from which @future cannot be invoked.
     */
    public static void recalculateSynchronously(Set<Id> accountIds) {
        performRecalculation(accountIds);
    }

    private static void performRecalculation(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        // Defensive copy: never mutate the caller's set, and drop nulls.
        Set<Id> ids = new Set<Id>(accountIds);
        ids.remove(null);
        if (ids.isEmpty()) {
            return;
        }

        // One aggregate query for all accounts. MAX ignores null Amounts,
        // so an account whose open Opportunities all have a null Amount
        // yields a null max and is correctly rated Warm (via presence in
        // the result set) rather than Hot.
        Set<Id> accountsWithOpenOpps = new Set<Id>();
        Map<Id, Decimal> maxOpenAmountByAccount = new Map<Id, Decimal>();

        for (AggregateResult result : [
            SELECT AccountId, MAX(Amount) maxAmount
            FROM Opportunity
            WHERE AccountId IN :ids AND IsClosed = false
            GROUP BY AccountId
        ]) {
            Id accountId = (Id) result.get('AccountId');
            accountsWithOpenOpps.add(accountId);
            maxOpenAmountByAccount.put(accountId, (Decimal) result.get('maxAmount'));
        }

        List<Account> accountsToUpdate = new List<Account>();

        for (Account acc : [SELECT Id, Rating FROM Account WHERE Id IN :ids]) {
            Decimal maxAmount = maxOpenAmountByAccount.get(acc.Id);

            String newRating;
            if (!accountsWithOpenOpps.contains(acc.Id)) {
                newRating = 'Cold';
            } else if (maxAmount != null && maxAmount >= HOT_THRESHOLD) {
                newRating = 'Hot';
            } else {
                newRating = 'Warm';
            }

            // Only write when the value changes: avoids unnecessary DML,
            // account record locks, and downstream automation firing.
            if (acc.Rating != newRating) {
                accountsToUpdate.add(new Account(Id = acc.Id, Rating = newRating));
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
