/**
 * Applies the standard product discount to new opportunity line items.
 *
 * What was changed from the requested implementation, and why:
 *
 * The request was to call PricingRules.standardDiscountFor(line.Product2Id)
 * once per line. That overload executes a SOQL query on every invocation,
 * so inserting up to 200 lines would execute up to 200 SOQL queries and
 * exceed the synchronous limit of 100 queries per transaction.
 *
 * Instead, this handler:
 *   1. Collects the products needed by lines whose Discount is null.
 *   2. Queries those products' families in bulk (one query, plus at most
 *      one query to resolve Product2Id from PricebookEntryId when
 *      Product2Id is not yet populated in a before-insert trigger).
 *   3. Calls the pure PricingRules.standardDiscountForFamily(String)
 *      overload for each line.
 *
 * PricingRules is not modified and its discount rules are not copied here:
 * the family-to-discount mapping remains owned solely by PricingRules.
 * This class only bulk-fetches the family needed to invoke that rule.
 */
public with sharing class LineItemDiscountHandler {

    public static void handleBeforeInsert(List<OpportunityLineItem> newLines) {
        if (newLines == null || newLines.isEmpty()) {
            return;
        }

        Set<Id> productIds = new Set<Id>();
        Set<Id> pricebookEntryIds = new Set<Id>();

        for (OpportunityLineItem line : newLines) {
            // Preserve any explicitly supplied discount, including 0.
            if (line.Discount != null) {
                continue;
            }
            if (line.Product2Id != null) {
                productIds.add(line.Product2Id);
            } else if (line.PricebookEntryId != null) {
                // Product2Id may not be populated from PricebookEntryId
                // yet when a before-insert trigger runs.
                pricebookEntryIds.add(line.PricebookEntryId);
            }
        }

        if (productIds.isEmpty() && pricebookEntryIds.isEmpty()) {
            return;
        }

        Map<Id, Id> productIdByPricebookEntryId = new Map<Id, Id>();
        if (!pricebookEntryIds.isEmpty()) {
            for (PricebookEntry entry : [
                SELECT Id, Product2Id
                FROM PricebookEntry
                WHERE Id IN :pricebookEntryIds
                WITH USER_MODE
            ]) {
                if (entry.Product2Id != null) {
                    productIdByPricebookEntryId.put(entry.Id, entry.Product2Id);
                    productIds.add(entry.Product2Id);
                }
            }
        }

        if (productIds.isEmpty()) {
            return;
        }

        Map<Id, Product2> productById = new Map<Id, Product2>([
            SELECT Id, Family
            FROM Product2
            WHERE Id IN :productIds
            WITH USER_MODE
        ]);

        for (OpportunityLineItem line : newLines) {
            if (line.Discount != null) {
                continue;
            }

            Id productId = line.Product2Id != null
                ? line.Product2Id
                : productIdByPricebookEntryId.get(line.PricebookEntryId);

            if (productId == null) {
                continue;
            }

            Product2 product = productById.get(productId);
            if (product == null) {
                continue;
            }

            line.Discount = PricingRules.standardDiscountForFamily(product.Family);
        }
    }
}
