public with sharing class CaseSurveyJob implements Queueable {
    private final Set<Id> caseIds;

    public CaseSurveyJob(Set<Id> caseIds) {
        // Defensive copy; Set<Id> is serializable Queueable state.
        this.caseIds = (caseIds == null) ? new Set<Id>() : new Set<Id>(caseIds);
    }

    public void execute(QueueableContext context) {
        if (caseIds.isEmpty()) {
            return;
        }

        Date activityDate = Date.today().addDays(2);
        List<Task> tasks = new List<Task>();

        // Re-query at execution time: only create a survey for cases that
        // are still closed and have a contact when the job actually runs.
        for (Case c : [
            SELECT Id, CaseNumber, ContactId
            FROM Case
            WHERE Id IN :caseIds
            AND IsClosed = true
            AND ContactId != null
        ]) {
            tasks.add(
                new Task(
                    WhatId = c.Id,
                    WhoId = c.ContactId,
                    Subject = 'CSAT survey: ' + c.CaseNumber,
                    ActivityDate = activityDate,
                    Status = 'Not Started'
                )
            );
        }

        if (!tasks.isEmpty()) {
            // allOrNone = false: one invalid Task must not fail the rest,
            // preserving the isolation one-job-per-case was meant to give.
            Database.insert(tasks, false);
        }
    }
}
