/**
 * @description Sends renewal reminder emails to Opportunity owners.
 *
 * IMPORTANT - why Messaging.sendEmail must NOT be called inside the loop:
 * Apex allows a maximum of 10 Messaging.sendEmail invocations per transaction.
 * Calling it once per Opportunity would throw an uncatchable
 * System.LimitException on the 11th call when processing up to 200 records,
 * aborting the entire transaction.
 *
 * Instead, this service builds all Messaging.SingleEmailMessage objects in
 * memory, makes a single bulk Messaging.sendEmail call, and passes
 * allOrNothing = false. Therefore a failure for one message (for example,
 * an inactive owner) is returned in that message's Messaging.SendEmailResult
 * and does not prevent the remaining emails from being sent.
 */
public with sharing class RenewalReminderService {

    public static Integer sendReminders(List<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        Set<Id> uniqueOpportunityIds = new Set<Id>();
        for (Id opportunityId : opportunityIds) {
            if (opportunityId != null) {
                uniqueOpportunityIds.add(opportunityId);
            }
        }

        if (uniqueOpportunityIds.isEmpty()) {
            return 0;
        }

        List<Messaging.SingleEmailMessage> emails = new List<Messaging.SingleEmailMessage>();

        for (Opportunity opp : [
            SELECT Id, Name, CloseDate, OwnerId, Owner.IsActive
            FROM Opportunity
            WHERE Id IN :uniqueOpportunityIds
            AND OwnerId != null
        ]) {
            if (!opp.Owner.IsActive) {
                continue;
            }

            String closeDateText = opp.CloseDate != null
                ? String.valueOf(opp.CloseDate)
                : 'not set';

            Messaging.SingleEmailMessage email = new Messaging.SingleEmailMessage();
            email.setTargetObjectId(opp.OwnerId);
            email.setSaveAsActivity(false);
            email.setSubject('Renewal due: ' + opp.Name);
            email.setPlainTextBody(
                'Hello,\n\n' +
                'The renewal for opportunity "' + opp.Name + '" is due.\n' +
                'Close date: ' + closeDateText + '\n\n' +
                'Please review the opportunity and follow up as appropriate.'
            );

            emails.add(email);
        }

        if (emails.isEmpty()) {
            return 0;
        }

        Messaging.SendEmailResult[] results;

        try {
            // allOrNothing = false allows successful messages to be sent even
            // when one or more other messages fail.
            results = Messaging.sendEmail(emails, false);
        } catch (Messaging.EmailException e) {
            System.debug(
                LoggingLevel.ERROR,
                'RenewalReminderService failed to send reminder emails: ' + e.getMessage()
            );
            return 0;
        }

        Integer sentCount = 0;

        for (Messaging.SendEmailResult result : results) {
            if (result.isSuccess()) {
                sentCount++;
            } else {
                for (Messaging.SendEmailError emailError : result.getErrors()) {
                    System.debug(
                        LoggingLevel.ERROR,
                        'Renewal reminder email failed: ' + emailError.getMessage()
                    );
                }
            }
        }

        return sentCount;
    }
}
