/**
 * Synchronises Contact mailing countries when an Account billing country changes.
 *
 * Deliberate deviation from the requested "load every Contact" approach:
 * this org has ~2.3 million Contacts, while a transaction may retrieve at most
 * 50,000 SOQL rows (and is also bounded by heap/CPU limits). Querying
 * [SELECT Id, AccountId, MailingCountry FROM Contact] unfiltered would throw a
 * LimitException before any logic ran, on every Account update.
 *
 * Instead this handler still issues exactly one SOQL query, outside any loop,
 * but filters it to the Contacts of only those Accounts whose BillingCountry
 * actually changed (AccountId is indexed). That keeps the handler bulk-safe
 * for the 200-record MDM batches without ever loading unrelated Contacts.
 */
public inherited sharing class AccountCountrySync {

    public static void handleAfterUpdate(List<Account> newAccounts, Map<Id, Account> oldAccountById) {
        if (newAccounts == null || newAccounts.isEmpty()
                || oldAccountById == null || oldAccountById.isEmpty()) {
            return;
        }

        Map<Id, String> newCountryByAccountId = new Map<Id, String>();
        Map<Id, String> oldCountryByAccountId = new Map<Id, String>();

        for (Account newAccount : newAccounts) {
            Account oldAccount = oldAccountById.get(newAccount.Id);
            if (oldAccount == null) {
                continue;
            }
            if (newAccount.BillingCountry != oldAccount.BillingCountry) {
                newCountryByAccountId.put(newAccount.Id, newAccount.BillingCountry);
                oldCountryByAccountId.put(newAccount.Id, oldAccount.BillingCountry);
            }
        }

        // No BillingCountry changed: leave every Contact alone and do not query at all.
        if (newCountryByAccountId.isEmpty()) {
            return;
        }

        List<Contact> contactsToUpdate = new List<Contact>();

        // The single, filtered query: only Contacts of the changed Accounts.
        for (Contact con : [
            SELECT Id, AccountId, MailingCountry
            FROM Contact
            WHERE AccountId IN :newCountryByAccountId.keySet()
        ]) {
            String newCountry = newCountryByAccountId.get(con.AccountId);
            String oldCountry = oldCountryByAccountId.get(con.AccountId);

            Boolean followsAccount = String.isBlank(con.MailingCountry)
                || con.MailingCountry == oldCountry;

            if (followsAccount && con.MailingCountry != newCountry) {
                con.MailingCountry = newCountry;
                contactsToUpdate.add(con);
            }
        }

