```javascript
import { LightningElement } from 'lwc';
import searchContacts from '@salesforce/apex/ContactController.searchContacts';

const DEBOUNCE_DELAY = 300;

export default class ContactSearch extends LightningElement {
    contacts = [];
    errorMessage;
    debounceTimeout;
    latestRequestId = 0;

    handleChange(event) {
        const detailValue =
            event.detail && typeof event.detail.value === 'string'
                ? event.detail.value
                : typeof event.detail === 'string'
                  ? event.detail
                  : undefined;
        const targetValue =
            event.target && typeof event.target.value === 'string'
                ? event.target.value
                : undefined;
        const rawValue = detailValue !== undefined ? detailValue : (targetValue ?? '');
        const searchTerm = String(rawValue).trim();

        if (this.debounceTimeout) {
            clearTimeout(this.debounceTimeout);
            this.debounceTimeout = undefined;
        }

        if (searchTerm.length < 2) {
            // Invalidate any in-flight request so its response cannot
            // repopulate results after they have been cleared.
            this.latestRequestId += 1;
            this.contacts = [];
            this.errorMessage = undefined;
            return;
        }

        this.debounceTimeout = setTimeout(() => {
            this.debounceTimeout = undefined;
            this.performSearch(searchTerm);
        }, DEBOUNCE_DELAY);
    }

    async performSearch(searchTerm) {
        const requestId = ++this.latestRequestId;
        try {
            const results = await searchContacts({ searchTerm });
            if (requestId !== this.latestRequestId) {
                return;
            }
            this.contacts = results || [];
            this.errorMessage = undefined;
        } catch (error) {
            if (requestId !== this.latestRequestId) {
                return;
            }
            this.contacts = [];
            this.errorMessage =
                error && error.body && error.body.message
                    ? error.body.message
                    : 'An unexpected error occurred';
        }
    }

    disconnectedCallback() {
        if (this.debounceTimeout) {
            clearTimeout(this.debounceTimeout);
            this.debounceTimeout = undefined;
        }
        // Invalidate any in-flight request.
        this.latestRequestId += 1;
    }
}
