import { LightningElement, api } from 'lwc';

export default class OrderLinesPanel extends LightningElement {
    @api lines = [];

    showError = false;

    handleReset() {
        Array.from(
            this.template.querySelectorAll('c-line-item-editor')
        ).forEach((editor) => editor.reset());
    }

    handleSubmit() {
        const editors = Array.from(
            this.template.querySelectorAll('c-line-item-editor')
        );

        // Validate every editor (no short-circuit) so all errors show at once.
        const results = editors.map((editor) => editor.validate());
        const allValid = results.every((result) => result === true);

        if (allValid) {
            this.showError = false;
            const lines = editors.map((editor) => editor.getValue());
            this.dispatchEvent(
                new CustomEvent('submit', {
                    detail: { lines },
                    bubbles: true,
                    composed: true
                })
            );
        } else {
            this.showError = true;
        }
    }
}
