import { LightningElement } from 'lwc';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';
import register from '@salesforce/apex/RegistrationController.register';

const BLOCKED_DOMAINS = new Set([
    'gmail.com',
    'yahoo.com',
    'hotmail.com',
    'outlook.com'
]);

export default class EventRegistrationForm extends LightningElement {
    fullName = '';
    email = '';
    company = '';

    handleFullNameChange(event) {
        this.fullName = event.detail.value;
    }

    handleEmailChange(event) {
        this.email = event.detail.value;
    }

    handleCompanyChange(event) {
        this.company = event.detail.value;
    }

    async handleRegister() {
        const inputs = [
            ...this.template.querySelectorAll('lightning-input')
        ];
        const emailInput =
            this.template.querySelector('[data-field="email"]') ||
            inputs.find((input) => input.dataset.field === 'email');

        if (emailInput && typeof emailInput.setCustomValidity === 'function') {
            const emailValue = (this.email ?? emailInput.value ?? '')
                .toString()
                .trim()
                .toLowerCase();
            const atIndex = emailValue.lastIndexOf('@');
            const domain =
                atIndex >= 0 ? emailValue.slice(atIndex + 1) : '';

            if (BLOCKED_DOMAINS.has(domain)) {
                emailInput.setCustomValidity('Use your work email address.');
            } else {
                emailInput.setCustomValidity('');
            }
        }

        let isValid = true;
        inputs.forEach((input) => {
            let reported;
            if (typeof input.reportValidity === 'function') {
                reported = input.reportValidity();
            }
            if (reported === false) {
                isValid = false;
            }
            if (input.validity && typeof input.validity.valid === 'boolean') {
                if (!input.validity.valid) {
                    isValid = false;
                }
            } else if (typeof input.checkValidity === 'function') {
                if (input.checkValidity() === false) {
                    isValid = false;
                }
            }
        });

        if (!isValid) {
            return;
        }

        try {
            await register({
                fullName: this.fullName,
                email: this.email,
                company: this.company
            });
            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Registered',
                    variant: 'success'
                })
            );
        } catch (error) {
            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Registration failed',
                    message: error.body.message,
                    variant: 'error'
                })
            );
        }
    }
}
