import { LightningElement, api } from 'lwc';

let nextInstanceId = 0;

export default class StatusListbox extends LightningElement {
    @api label;

    _options = [];
    _value;
    _activeValue;
    _instanceId;

    constructor() {
        super();
        this._instanceId = `status-listbox-${nextInstanceId++}`;
    }

    @api
    get options() {
        return this._options;
    }

    set options(value) {
        this._options = Array.isArray(value) ? value : [];
        if (this._options.length === 0) {
            return;
        }
        if (!this._options.some((option) => option.value === this._activeValue)) {
            this._syncActiveFromValue();
        }
    }

    @api
    get value() {
        return this._value;
    }

    set value(newValue) {
        const oldValue = this._value;
        this._value = newValue;
        if (newValue !== oldValue) {
            this._syncActiveFromValue();
        }
    }

    _syncActiveFromValue() {
        if (!this._options || this._options.length === 0) {
            this._activeValue = this._value;
            return;
        }
        const selected = this._options.find(
            (option) => option.value === this._value
        );
        this._activeValue = selected
            ? selected.value
            : this._options[0].value;
    }

    get activeIndex() {
        if (!this._options || this._options.length === 0) {
            return -1;
        }
        let index = this._options.findIndex(
            (option) => option.value === this._activeValue
        );
        if (index !== -1) {
            return index;
        }
        index = this._options.findIndex(
            (option) => option.value === this._value
        );
        if (index !== -1) {
            return index;
        }
        return 0;
    }

    get activeId() {
        const index = this.activeIndex;
        return index >= 0 ? `${this._instanceId}-${index}` : '';
    }

    get renderedOptions() {
        const options = this._options || [];
        return options.map((option, index) => ({
            id: `${this._instanceId}-${index}`,
            index,
            value: option.value,
            label: option.label,
            ariaSelected: option.value === this._value ? 'true' : 'false'
        }));
    }

    handleKeyDown(event) {
        const handledKeys = [
            'ArrowDown',
            'ArrowUp',
            'Home',
            'End',
            'Enter',
            ' '
        ];

        if (!handledKeys.includes(event.key)) {
            return;
        }

        event.preventDefault();

        if (!this._options || this._options.length === 0) {
            return;
        }

        const currentIndex = this.activeIndex;
        let newIndex = currentIndex;

        switch (event.key) {
            case 'ArrowDown':
                newIndex = Math.min(currentIndex + 1, this._options.length - 1);
                this._activeValue = this._options[newIndex].value;
                break;
            case 'ArrowUp':
                newIndex = Math.max(currentIndex - 1, 0);
                this._activeValue = this._options[newIndex].value;
                break;
            case 'Home':
                this._activeValue = this._options[0].value;
                break;
            case 'End':
                this._activeValue =
                    this._options[this._options.length - 1].value;
                break;
            case 'Enter':
            case ' ':
                if (currentIndex >= 0) {
                    this._selectValue(this._options[currentIndex].value);
                }
                break;
            default:
                break;
        }
    }

    handleOptionClick(event) {
        const index = Number(event.currentTarget.dataset.index);
        let selectedValue;
        if (
            !Number.isNaN(index) &&
            this._options &&
            this._options[index]
        ) {
            selectedValue = this._options[index].value;
        } else {
            selectedValue = event.currentTarget.dataset.value;
        }
        this._activeValue = selectedValue;
        this._selectValue(selectedValue);
    }

    _selectValue(selectedValue) {
        this._activeValue = selectedValue;
        if (selectedValue === this._value) {
            return;
        }
        this._value = selectedValue;
        this.dispatchEvent(
            new CustomEvent('change', {
                detail: { value: selectedValue },
                bubbles: true,
                composed: true
            })
        );
    }
}
