import { LightningElement, api } from 'lwc';

export default class TaskChecklist extends LightningElement {
    @api heading;

    _tasks = [];
    items = [];
    newLabel = '';
    nextId = 1;

    @api
    get tasks() {
        return this._tasks;
    }

    set tasks(value) {
        this._tasks = value;
        this.items = value
            ? value.map((task) => ({ ...task }))
            : [];
    }

    get displayHeading() {
        return this.heading ? String(this.heading).toUpperCase() : '';
    }

    get remaining() {
        return this.items.filter((task) => !task.done).length;
    }

    handleLabelChange(event) {
        const value = event.detail?.value ?? event.target?.value ?? '';
        this.newLabel = value;
    }

    handleAdd() {
        const label = this.newLabel ? String(this.newLabel).trim() : '';
        if (!label) {
            return;
        }
        let id;
        do {
            id = `new-${this.nextId++}`;
        } while (this.items.some((task) => String(task.id) === id));

        this.items = [...this.items, { id, label, done: false }];
        this.newLabel = '';
        this.dispatchEvent(
            new CustomEvent('taskadded', {
                detail: { label },
                bubbles: true,
                composed: true
            })
        );
    }

    handleToggle(event) {
        const id = event.target?.dataset?.id;
        if (id === undefined || id === null) {
            return;
        }
        let found = false;
        const updated = this.items.map((task) => {
            if (String(task.id) === String(id)) {
                found = true;
                return { ...task, done: !task.done };
            }
            return task;
        });
        if (found) {
            this.items = updated;
        }
    }
}
