public with sharing class EmployerService {

    /**
     * Sets each contact's current employer using NPSP's standard
     * Primary Affiliation mechanism.
     *
     * Setting Contact.npsp__Primary_Affiliation__c causes NPSP's
     * affiliation automation to:
     *  - create the Affiliation if one does not already exist, or reuse
     *    the existing Affiliation for that contact/organization;
     *  - mark that Affiliation Current and Primary;
     *  - mark any previous Primary Affiliation Former and non-Primary,
     *    with an End Date of today.
     *
     * Therefore this method deliberately does not create
     * npe5__Affiliation__c records manually, does not demote the previous
     * affiliation manually, and does not change Contact.AccountId, so
     * contacts remain in their Household Accounts.
     *
     * Bulk usage: 1 SOQL and 1 DML statement.
     */
    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        Map<Id, Id> desiredEmployerByContactId = new Map<Id, Id>();
        for (Id contactId : employerByContactId.keySet()) {
            Id employerId = employerByContactId.get(contactId);
            if (contactId != null && employerId != null) {
                desiredEmployerByContactId.put(contactId, employerId);
            }
        }

        if (desiredEmployerByContactId.isEmpty()) {
            return;
        }

        List<Contact> contactsToUpdate = new List<Contact>();

        for (Contact contactRecord : [
            SELECT Id, npsp__Primary_Affiliation__c
            FROM Contact
            WHERE Id IN :desiredEmployerByContactId.keySet()
        ]) {
            Id desiredEmployerId = desiredEmployerByContactId.get(contactRecord.Id);

            // No change if this organization is already the primary
            // affiliation; avoids an unnecessary update and any
            // duplicate affiliation.
            if (contactRecord.npsp__Primary_Affiliation__c != desiredEmployerId) {
                contactsToUpdate.add(
                    new Contact(
                        Id = contactRecord.Id,
                        npsp__Primary_Affiliation__c = desiredEmployerId
                    )
                );
            }
        }

        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }
}
