public with sharing class GiftImportService {

    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;        // the donor's personal email
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;        // the matched or created contact
        public Id opportunityId;    // the created donation
        public String errorMessage; // NPSP's failure information when success is false
    }

    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        List<ImportResult> results = new List<ImportResult>();

        if (gifts == null || gifts.isEmpty()) {
            return results;
        }

        // Stage one NPSP Data Import record per gift. These records remain
        // in the org as the audit trail of what was imported.
        List<npsp__DataImport__c> staged = new List<npsp__DataImport__c>();
        for (WebGift gift : gifts) {
            npsp__DataImport__c di = new npsp__DataImport__c();
            if (gift != null) {
                di.npsp__Contact1_Firstname__c = gift.firstName;
                di.npsp__Contact1_Lastname__c = gift.lastName;
                di.npsp__Contact1_Personal_Email__c = gift.email;
                di.npsp__Donation_Amount__c = gift.amount;
                di.npsp__Donation_Date__c = gift.giftDate;
            }
            di.npsp__Donation_Donor__c = 'Contact1';
            staged.add(di);
        }
        insert staged;

        // Use the org's Data Import settings. The required behaviour for
        // these web gifts is the documented default: match contacts on
        // first name, last name and email, and never match an existing
        // donation (always create a new Opportunity). Setting these two
        // values on the in-memory copy also covers orgs in which the
        // hierarchy setting has not been saved yet; all other org
        // settings (household model, etc.) are used exactly as configured.
        // The custom setting itself is not modified.
        npsp__Data_Import_Settings__c diSettings =
            npsp__Data_Import_Settings__c.getOrgDefaults();
        if (diSettings == null) {
            diSettings = new npsp__Data_Import_Settings__c();
        }
        diSettings.npsp__Contact_Matching_Rule__c = 'Firstname,Lastname,Email';
        diSettings.npsp__Donation_Matching_Behavior__c = 'Do Not Match';

        // Process synchronously, in this transaction, through NPSP's own
        // data import API so that NPSP contact matching, household
        // creation and donation processing rules apply. NPSP normally
        // marks rejected rows as Failed and continues with the rest; if
        // the bulk call ever throws, roll back only its work (the staged
        // records, inserted before the savepoint, are kept) and retry
        // row-by-row so one rejected gift cannot stop the others.
        Map<Id, String> processingErrorsByDiId = new Map<Id, String>();
        System.Savepoint bulkSavepoint = Database.setSavepoint();
        try {
            npsp.BDI_DataImport_API.processDataImportRecords(diSettings, staged, false);
        } catch (Exception bulkEx) {
            Database.rollback(bulkSavepoint);
            for (npsp__DataImport__c di : staged) {
                System.Savepoint rowSavepoint = Database.setSavepoint();
                try {
                    npsp.BDI_DataImport_API.processDataImportRecords(
                        diSettings,
                        new List<npsp__DataImport__c>{ di },
                        false
                    );
                } catch (Exception rowEx) {
                    Database.rollback(rowSavepoint);
                    processingErrorsByDiId.put(di.Id, rowEx.getMessage());
                }
            }
        }

        // Build the results from the processed Data Import records as
        // written back by NPSP, in input order.
        Map<Id, npsp__DataImport__c> processedById = new Map<Id, npsp__DataImport__c>(
            [
                SELECT
                    Id,
                    npsp__Status__c,
                    npsp__Contact1Imported__c,
                    npsp__DonationImported__c,
                    npsp__FailureInformation__c
                FROM npsp__DataImport__c
                WHERE Id IN :staged
            ]
        );

        for (npsp__DataImport__c di : staged) {
            ImportResult result = new ImportResult();
            npsp__DataImport__c processed = processedById.get(di.Id);

            if (processed == null) {
                result.success = false;
                result.errorMessage = processingErrorsByDiId.get(di.Id);
            } else {
                result.success = (processed.npsp__Status__c == 'Imported');
                result.contactId = processed.npsp__Contact1Imported__c;
                result.opportunityId = processed.npsp__DonationImported__c;
                if (result.success == true) {
                    result.errorMessage = null;
                } else if (String.isNotBlank(processed.npsp__FailureInformation__c)) {
                    result.errorMessage = processed.npsp__FailureInformation__c;
                } else if (processingErrorsByDiId.containsKey(di.Id)) {
                    result.errorMessage = processingErrorsByDiId.get(di.Id);
                } else {
                    result.errorMessage = processed.npsp__FailureInformation__c;
                }
            }
            results.add(result);
        }

        return results;
    }
}
