public with sharing class GauAllocationService {

    public class AllocationException extends Exception {}

    /**
     * Replaces the Opportunity's direct GAU allocations with percent-based allocations.
     *
     * Only npsp__Percent__c is populated (never npsp__Amount__c). NPSP's native
     * allocation logic derives npsp__Amount__c from the percentage and the
     * Opportunity Amount, and recalculates it when the Opportunity Amount
     * changes later, so the allocations stay correct with no further code.
     */
    public static List<npsp__Allocation__c> allocateByPercent(
        Id opportunityId,
        Map<Id, Decimal> percentByGauId
    ) {
        // ---------- Validate everything before changing any data ----------

        if (opportunityId == null) {
            throw new AllocationException('An Opportunity Id is required.');
        }
        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('At least one GAU allocation percentage is required.');
        }

        Decimal totalPercent = 0;
        for (Id gauId : percentByGauId.keySet()) {
            if (gauId == null) {
                throw new AllocationException('A GAU Id is required for every allocation.');
            }
            Decimal percent = percentByGauId.get(gauId);
            if (percent == null || percent <= 0) {
                throw new AllocationException(
                    'Every allocation percentage must be greater than 0.'
                );
            }
            totalPercent += percent;
        }
        if (totalPercent > 100) {
            throw new AllocationException(
                'Allocation percentages cannot add up to more than 100%.'
            );
        }

        // The Opportunity must exist.
        List<Opportunity> opportunities = [
            SELECT Id
            FROM Opportunity
            WHERE Id = :opportunityId
            LIMIT 1
        ];
        if (opportunities.isEmpty()) {
            throw new AllocationException('Opportunity not found: ' + opportunityId);
        }

        // Every referenced GAU must exist and be active.
        Map<Id, npsp__General_Accounting_Unit__c> gausById =
            new Map<Id, npsp__General_Accounting_Unit__c>([
                SELECT Id, Name, npsp__Active__c
                FROM npsp__General_Accounting_Unit__c
                WHERE Id IN :percentByGauId.keySet()
            ]);
        for (Id gauId : percentByGauId.keySet()) {
            npsp__General_Accounting_Unit__c gau = gausById.get(gauId);
            if (gau == null) {
                throw new AllocationException('General Accounting Unit not found: ' + gauId);
            }
            if (gau.npsp__Active__c != true) {
                throw new AllocationException(
                    'General Accounting Unit is inactive: ' + gau.Name
                );
            }
        }

        // ---------- Replace existing direct Opportunity allocations ----------
        // An Allocation's parent is exactly one of Opportunity, Payment,
        // Campaign or Recurring Donation. Only direct Opportunity allocations
        // are replaced; Payment/Campaign/Recurring Donation allocations are
        // left untouched.
        List<npsp__Allocation__c> existingAllocations = [
            SELECT Id
            FROM npsp__Allocation__c
            WHERE npsp__Opportunity__c = :opportunityId
            AND npsp__Payment__c = null
            AND npsp__Campaign__c = null
            AND npsp__Recurring_Donation__c = null
        ];
        if (!existingAllocations.isEmpty()) {
            delete existingAllocations;
        }

        List<npsp__Allocation__c> newAllocations = new List<npsp__Allocation__c>();
        for (Id gauId : percentByGauId.keySet()) {
            newAllocations.add(new npsp__Allocation__c(
                npsp__Opportunity__c = opportunityId,
                npsp__General_Accounting_Unit__c = gauId,
                npsp__Percent__c = percentByGauId.get(gauId)
                // npsp__Amount__c intentionally left null: NPSP calculates it
                // from the percent and keeps it in sync with the Opportunity Amount.
            ));
        }
        insert newAllocations;

        // Re-query so the returned records reflect the Amount calculated by NPSP.
        return [
            SELECT Id,
                npsp__Opportunity__c,
