public with sharing class HouseholdService {

    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('members must not be null or empty');
        }

        Contact primaryContact = members[0];
        primaryContact.AccountId = null;

        // Insert the primary contact on its own so that NPSP's Household
        // Account model creates exactly one household for it, assigns that
        // contact as the household's primary contact, and applies automatic
        // household naming and greetings. Inserting all members without an
        // account at once would cause NPSP to create a household per contact.
        insert primaryContact;

        Id householdId = [
            SELECT AccountId
            FROM Contact
            WHERE Id = :primaryContact.Id
            LIMIT 1
        ].AccountId;

        if (householdId == null) {
            // Fallback for an org in which NPSP did not auto-create an
            // account for the contact: create the Household Account account
            // explicitly (letting NPSP populate its name) and attach the
            // primary contact to it.
            Id householdRecordTypeId = Schema.SObjectType.Account
                .getRecordTypeInfosByDeveloperName()
                .get('HH_Account')
                .getRecordTypeId();

            Account household = new Account(
                RecordTypeId = householdRecordTypeId,
                npe01__One2OneContact__c = primaryContact.Id
            );
            insert household;

            householdId = household.Id;
            primaryContact.AccountId = householdId;
            update primaryContact;
        } else {
            primaryContact.AccountId = householdId;
        }

        if (members.size() > 1) {
            List<Contact> remainingMembers = new List<Contact>();
            for (Integer i = 1; i < members.size(); i++) {
                members[i].AccountId = householdId;
                remainingMembers.add(members[i]);
            }
            // These contacts join the existing household, so NPSP does not
            // create any additional accounts for them.
            insert remainingMembers;
        }

        // NPSP normally sets this when it creates the household, but ensure
        // the first contact is recorded as the household's primary contact.
        Account householdAccount = [
            SELECT Id, npe01__One2OneContact__c
            FROM Account
            WHERE Id = :householdId
            LIMIT 1
        ];
        if (householdAccount.npe01__One2OneContact__c != primaryContact.Id) {
            householdAccount.npe01__One2OneContact__c = primaryContact.Id;
            update householdAccount;
        }

        return householdId;
    }
}
