public with sharing class SoftCreditService {

    public class SoftCreditException extends Exception {}

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return;
        }

        Set<Id> opportunityIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();

        for (SoftCreditRequest request : requests) {
            if (request == null) {
                throw new SoftCreditException('Soft credit request cannot be null.');
            }
            if (request.opportunityId == null) {
                throw new SoftCreditException('Soft credit request must specify an opportunity.');
            }
            if (request.contactId == null) {
                throw new SoftCreditException('Soft credit request must specify a contact.');
            }
            opportunityIds.add(request.opportunityId);
            contactIds.add(request.contactId);
        }

        // SOQL 1: Opportunities needed for validation.
        Map<Id, Opportunity> opportunitiesById = new Map<Id, Opportunity>([
            SELECT Id, Amount, npsp__Primary_Contact__c
            FROM Opportunity
            WHERE Id IN :opportunityIds
        ]);

        // Validate the entire call before performing any DML.
        for (SoftCreditRequest request : requests) {
            Opportunity opp = opportunitiesById.get(request.opportunityId);
            if (opp == null) {
                throw new SoftCreditException(
                    'Opportunity not found: ' + request.opportunityId
                );
            }
            if (request.contactId == opp.npsp__Primary_Contact__c) {
                throw new SoftCreditException(
                    'The opportunity primary contact cannot receive a partial soft credit.'
                );
            }
            if (request.amount == null) {
                throw new SoftCreditException('Partial soft credit amount cannot be null.');
            }
            if (request.amount <= 0) {
                throw new SoftCreditException('Partial soft credit amount must be positive.');
            }
            if (opp.Amount == null || request.amount > opp.Amount) {
                throw new SoftCreditException(
                    'Partial soft credit amount cannot exceed the opportunity amount.'
                );
            }
        }

        Map<String, Schema.DescribeFieldResult> pscFields =
            getPartialSoftCreditFieldDescribes();
        String pscContactLookupField = getPscContactLookupField(pscFields);

        // Normally not needed in NPSP, where Contact_Name__c is the Contact
        // lookup. This supports orgs in which it is instead a writable text
        // field, while staying within the query limit in that configuration.
        Map<Id, Contact> contactsById = new Map<Id, Contact>();
        if (needsContactName(pscFields)) {
            // SOQL 2 (only in the text-field configuration): Contact names.
            contactsById = new Map<Id, Contact>([
                SELECT Id, Name
                FROM Contact
                WHERE Id IN :contactIds
            ]);
        }

        // SOQL: Existing Opportunity Contact Roles for the requested pairs.
        List<OpportunityContactRole> existingOcrs = [
            SELECT Id, OpportunityId, ContactId, Role
            FROM OpportunityContactRole
            WHERE OpportunityId IN :opportunityIds
            AND ContactId IN :contactIds
        ];

        Map<String, List<OpportunityContactRole>> ocrsByPair =
            new Map<String, List<OpportunityContactRole>>();
        for (OpportunityContactRole ocr : existingOcrs) {
            String key = pairKey(ocr.OpportunityId, ocr.ContactId);
            if (!ocrsByPair.containsKey(key)) {
                ocrsByPair.put(key, new List<OpportunityContactRole>());
            }
            ocrsByPair.get(key).add(ocr);
        }

        // SOQL: Existing Partial Soft Credits on the requested opportunities.
        // Matching to a requested contact is done in Apex using whichever
        // NPSP field is the Contact lookup in this org.
        List<npsp__Partial_Soft_Credit__c> existingPscs = [
            SELECT Id,
                   npsp__Opportunity__c,
                   npsp__Contact__c,
                   npsp__Contact_Name__c,
                   npsp__Amount__c,
                   npsp__Role_Name__c,
                   npsp__Contact_Role_ID__c
            FROM npsp__Partial_Soft_Credit__c
            WHERE npsp__Opportunity__c IN :opportunityIds
        ];

        Map<String, List<npsp__Partial_Soft_Credit__c>> pscsByPair =
            new Map<String, List<npsp__Partial_Soft_Credit__c>>();
        for (npsp__Partial_Soft_Credit__c psc : existingPscs) {
            Id pscContactId = getPscContactId(psc, pscContactLookupField, pscFields);
            if (pscContactId == null || !contactIds.contains(pscContactId)) {
                continue;
            }
            String key = pairKey(psc.npsp__Opportunity__c, pscContactId);
            if (!pscsByPair.containsKey(key)) {
                pscsByPair.put(key, new List<npsp__Partial_Soft_Credit__c>());
            }
            pscsByPair.get(key).add(psc);
        }

        Map<String, OpportunityContactRole> keptOcrByPair =
            new Map<String, OpportunityContactRole>();
        Map<String, npsp__Partial_Soft_Credit__c> keptPscByPair =
            new Map<String, npsp__Partial_Soft_Credit__c>();
        List<OpportunityContactRole> ocrsToUpsert = new List<OpportunityContactRole>();
        List<OpportunityContactRole> duplicateOcrsToDelete =
            new List<OpportunityContactRole>();
        List<npsp__Partial_Soft_Credit__c> duplicatePscsToDelete =
            new List<npsp__Partial_Soft_Credit__c>();

        for (SoftCreditRequest request : requests) {
            String key = pairKey(request.opportunityId, request.contactId);

            List<npsp__Partial_Soft_Credit__c> pscsForPair = pscsByPair.get(key);
            npsp__Partial_Soft_Credit__c keptPsc;
            if (pscsForPair != null && !pscsForPair.isEmpty()) {
                keptPsc = pscsForPair[0];
                keptPscByPair.put(key, keptPsc);
                for (Integer i = 1; i < pscsForPair.size(); i++) {
                    duplicatePscsToDelete.add(pscsForPair[i]);
                }
            }

            List<OpportunityContactRole> ocrsForPair = ocrsByPair.get(key);
            OpportunityContactRole keptOcr;
            if (ocrsForPair != null && !ocrsForPair.isEmpty()) {
                // Prefer the role already linked to the kept soft credit.
                keptOcr = ocrsForPair[0];
                if (keptPsc != null && keptPsc.npsp__Contact_Role_ID__c != null) {
                    for (OpportunityContactRole candidate : ocrsForPair) {
                        if (String.valueOf(candidate.Id) ==
                            keptPsc.npsp__Contact_Role_ID__c) {
                            keptOcr = candidate;
                            break;
                        }
                    }
                }
                for (OpportunityContactRole candidate : ocrsForPair) {
                    if (candidate.Id != keptOcr.Id) {
                        duplicateOcrsToDelete.add(candidate);
                    }
                }

                if (keptOcr.Role != request.role) {
                    keptOcr.Role = request.role;
                    ocrsToUpsert.add(keptOcr);
                }
            } else {
                keptOcr = new OpportunityContactRole(
                    OpportunityId = request.opportunityId,
                    ContactId = request.contactId,
                    Role = request.role
                );
                ocrsToUpsert.add(keptOcr);
            }
            keptOcrByPair.put(key, keptOcr);
        }

        // DML 1: Create or correct the single contact role for each pair.
        // After this, newly created roles have Ids for linking soft credits.
        if (!ocrsToUpsert.isEmpty()) {
            upsert ocrsToUpsert;
        }

        List<npsp__Partial_Soft_Credit__c> pscsToUpsert =
            new List<npsp__Partial_Soft_Credit__c>();

        for (SoftCreditRequest request : requests) {
            String key = pairKey(request.opportunityId, request.contactId);
            OpportunityContactRole ocr = keptOcrByPair.get(key);
            npsp__Partial_Soft_Credit__c psc = keptPscByPair.get(key);
            Boolean isNew = false;

            if (psc == null) {
                isNew = true;
                psc = new npsp__Partial_Soft_Credit__c();
                psc.npsp__Opportunity__c = request.opportunityId;
            }

            psc.npsp__Amount__c = request.amount;
            psc.npsp__Role_Name__c = request.role;
            psc.npsp__Contact_Role_ID__c = String.valueOf(ocr.Id);

            Contact contact = contactsById.get(request.contactId);
            setPscContact(
                psc,
                request.contactId,
                contact == null ? null : contact.Name,
                pscFields,
                isNew
            );

            pscsToUpsert.add(psc);
        }

        // DML 2: Create or update the single partial soft credit for each pair.
        if (!pscsToUpsert.isEmpty()) {
            upsert pscsToUpsert;
        }

        // The kept soft credit has been repointed above before any duplicate
        // role is removed, so these deletions cannot orphan the kept record.
        // DML 3: Remove any pre-existing duplicate contact roles.
        if (!duplicateOcrsToDelete.isEmpty()) {
            delete duplicateOcrsToDelete;
        }

        // DML 4: Remove any pre-existing duplicate partial soft credits.
        if (!duplicatePscsToDelete.isEmpty()) {
            delete duplicatePscsToDelete;
        }
    }

    private static String pairKey(Id opportunityId, Id contactId) {
        return String.valueOf(opportunityId) + '|' + String.valueOf(contactId);
    }

    private static Map<String, Schema.DescribeFieldResult>
    getPartialSoftCreditFieldDescribes() {
        Map<String, Schema.DescribeFieldResult> result =
            new Map<String, Schema.DescribeFieldResult>();
        Map<String, Schema.SObjectField> fieldsByName =
            npsp__Partial_Soft_Credit__c.SObjectType
                .getDescribe()
                .fields
                .getMap();

        for (String fieldName : fieldsByName.keySet()) {
            result.put(fieldName, fieldsByName.get(fieldName).getDescribe());
        }
        return result;
    }

    private static String getPscContactLookupField(
        Map<String, Schema.DescribeFieldResult> pscFields
    ) {
        // In NPSP, Contact_Name__c is the Contact lookup and Contact__c is a
        // formula. Prefer it, but support the reverse layout as well.
        for (String fieldName : new List<String>{
            'npsp__contact_name__c',
            'npsp__contact__c'
        }) {
            Schema.DescribeFieldResult fieldDescribe = pscFields.get(fieldName);
            if (fieldDescribe != null &&
                fieldDescribe.getType() == Schema.DisplayType.REFERENCE) {
                return fieldName;
            }
        }
        return null;
    }

    private static Id getPscContactId(
        npsp__Partial_Soft_Credit__c psc,
        String lookupField,
        Map<String, Schema.DescribeFieldResult> pscFields
    ) {
        if (lookupField != null) {
            Object value = psc.get(lookupField);
            return value == null ? null : (Id) value;
        }

        // Fallback for a text representation of the Contact Id.
        for (String fieldName : new List<String>{
            'npsp__contact__c',
            'npsp__contact_name__c'
        }) {
            Schema.DescribeFieldResult fieldDescribe = pscFields.get(fieldName);
            if (fieldDescribe == null) {
                continue;
            }
            Object value = psc.get(fieldName);
            if (value == null) {
                continue;
            }
            try {
                return Id.valueOf(String.valueOf(value));
            } catch (Exception ignored) {
                // Not an Id value; try the other field.
            }
        }
        return null;
    }

    private static Boolean needsContactName(
        Map<String, Schema.DescribeFieldResult> pscFields
    ) {
        Schema.DescribeFieldResult fieldDescribe =
            pscFields.get('npsp__contact_name__c');
        return fieldDescribe != null &&
               fieldDescribe.isCreateable() &&
               !fieldDescribe.isCalculated() &&
               (fieldDescribe.getType() == Schema.DisplayType.STRING ||
                fieldDescribe.getType() == Schema.DisplayType.TEXTAREA);
    }

    private static void setPscContact(
        npsp__Partial_Soft_Credit__c psc,
        Id contactId,
        String contactName,
        Map<String, Schema.DescribeFieldResult> pscFields,
        Boolean isNew
    ) {
        for (String fieldName : new List<String>{
            'npsp__contact_name__c',
            'npsp__contact__c'
        }) {
            Schema.DescribeFieldResult fieldDescribe = pscFields.get(fieldName);
            if (fieldDescribe == null || fieldDescribe.isCalculated()) {
                continue;
            }
            if (isNew && !fieldDescribe.isCreateable()) {
                continue;
            }
            if (!isNew && !fieldDescribe.isUpdateable()) {
                continue;
            }

            if (fieldDescribe.getType() == Schema.DisplayType.REFERENCE) {
                psc.put(fieldName, contactId);
            } else if (fieldName == 'npsp__contact_name__c') {
                if (contactName != null) {
                    psc.put(fieldName, contactName);
                }
            } else if (fieldDescribe.getType() == Schema.DisplayType.STRING ||
                       fieldDescribe.getType() == Schema.DisplayType.TEXTAREA) {
                psc.put(fieldName, String.valueOf(contactId));
            }
        }
    }
