public with sharing class GiftService {

    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException('Amount must be greater than zero.');
        }
        if (contactId == null) {
            throw new IllegalArgumentException('Contact does not exist: null');
        }

        Date effectiveGiftDate = (giftDate != null) ? giftDate : Date.today();

        List<Contact> contacts = [
            SELECT Id, FirstName, LastName, AccountId
            FROM Contact
            WHERE Id = :contactId
            LIMIT 1
        ];
        if (contacts.isEmpty()) {
            throw new IllegalArgumentException('Contact does not exist: ' + contactId);
        }
        Contact donor = contacts[0];
        if (donor.AccountId == null) {
            throw new IllegalArgumentException('Contact has no household account: ' + contactId);
        }

        String formattedDate = DateTime.newInstanceGmt(
            effectiveGiftDate.year(),
            effectiveGiftDate.month(),
            effectiveGiftDate.day()
        ).formatGmt('yyyy-MM-dd');

        List<String> nameParts = new List<String>();
        if (String.isNotBlank(donor.FirstName)) {
            nameParts.add(donor.FirstName.trim());
        }
        if (String.isNotBlank(donor.LastName)) {
            nameParts.add(donor.LastName.trim());
        }
        String oppName = String.join(nameParts, ' ') + ' Donation ' + formattedDate;
        oppName = oppName.trim();

        // Household members (includes the donor) for contact roles.
        List<Contact> householdMembers = [
            SELECT Id
            FROM Contact
            WHERE AccountId = :donor.AccountId
        ];

        Opportunity opp = new Opportunity(
            Name = oppName,
            AccountId = donor.AccountId,
            npsp__Primary_Contact__c = donor.Id,
            Amount = amount,
            CloseDate = effectiveGiftDate,
            StageName = 'Closed Won'
        );
        insert opp;

        // NPSP TDTM triggers may already have created contact roles for the
        // primary contact / household and a payment for a Closed Won gift.
        // Reconcile with what NPSP created instead of blindly inserting, so
        // we never end up with duplicate roles or duplicate payments.
        reconcileContactRoles(opp.Id, donor.Id, householdMembers);
        reconcilePayment(opp.Id, amount, effectiveGiftDate);

        return opp.Id;
    }

    private static void reconcileContactRoles(
        Id opportunityId,
        Id primaryContactId,
        List<Contact> householdMembers
    ) {
        List<OpportunityContactRole> existing = [
            SELECT Id, ContactId, Role, IsPrimary
            FROM OpportunityContactRole
            WHERE OpportunityId = :opportunityId
            ORDER BY CreatedDate ASC, Id ASC
        ];

        Map<Id, OpportunityContactRole> keeperByContactId =
            new Map<Id, OpportunityContactRole>();
        List<OpportunityContactRole> duplicatesToDelete =
            new List<OpportunityContactRole>();

        for (OpportunityContactRole ocr : existing) {
            if (keeperByContactId.containsKey(ocr.ContactId)) {
                duplicatesToDelete.add(ocr);
            } else {
                keeperByContactId.put(ocr.ContactId, ocr);
            }
        }
        if (!duplicatesToDelete.isEmpty()) {
            delete duplicatesToDelete;
        }

        List<OpportunityContactRole> toInsert = new List<OpportunityContactRole>();
        List<OpportunityContactRole> toUpdate = new List<OpportunityContactRole>();

        for (Contact member : householdMembers) {
            Boolean isPrimary = (member.Id == primaryContactId);
            String desiredRole = isPrimary ? 'Donor' : 'Household Member';

            OpportunityContactRole existingOcr = keeperByContactId.get(member.Id);
            if (existingOcr == null) {
                toInsert.add(new OpportunityContactRole(
                    OpportunityId = opportunityId,
                    ContactId = member.Id,
                    Role = desiredRole,
                    IsPrimary = isPrimary
                ));
            } else if (existingOcr.Role != desiredRole || existingOcr.IsPrimary != isPrimary) {
                existingOcr.Role = desiredRole;
                existingOcr.IsPrimary = isPrimary;
                toUpdate.add(existingOcr);
            }
        }

        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
        if (!toInsert.isEmpty()) {
            insert toInsert;
        }
    }

    private static void reconcilePayment(Id opportunityId, Decimal amount, Date giftDate) {
        List<npe01__OppPayment__c> existingPayments = [
            SELECT Id, npe01__Payment_Amount__c, npe01__Payment_Date__c,
                   npe01__Scheduled_Date__c, npe01__Paid__c
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :opportunityId
            ORDER BY CreatedDate ASC, Id ASC
        ];

        if (existingPayments.isEmpty()) {
            insert new npe01__OppPayment__c(
                npe01__Opportunity__c = opportunityId,
                npe01__Payment_Amount__c = amount,
                npe01__Payment_Date__c = giftDate,
                npe01__Scheduled_Date__c = giftDate,
                npe01__Paid__c = true
            );
            return;
        }

        // Keep exactly one payment: correct the first, remove any duplicates
        // NPSP or other automation may have created in addition to it.
        npe01__OppPayment__c keeper = existingPayments[0];

        List<npe01__OppPayment__c> duplicatesToDelete = new List<npe01__OppPayment__c>();
        for (Integer i = 1; i < existingPayments.size(); i++) {
            duplicatesToDelete.add(existingPayments[i]);
        }
        if (!duplicatesToDelete.isEmpty()) {
            delete duplicatesToDelete;
        }

        if (keeper.npe01__Payment_Amount__c != amount
            || keeper.npe01__Payment_Date__c != giftDate
            || keeper.npe01__Scheduled_Date__c != giftDate
            || keeper.npe01__Paid__c != true) {
            keeper.npe01__Payment_Amount__c = amount;
            keeper.npe01__Payment_Date__c = giftDate;
            keeper.npe01__Scheduled_Date__c = giftDate;
            keeper.npe01__Paid__c = true;
            update keeper;
        }
    }
}
