public with sharing class FamilyService {

    /**
     * Records each supplied parent as a current Parent of the child.
     *
     * Only the child -> parent relationship is inserted explicitly.
     * Under NPSP's default "List Setting" reciprocal method, the NPSP
     * relationship trigger automatically creates the reciprocal
     * parent -> child relationship, selects Son, Daughter or Child
     * from the Parent Relationship Lookup according to the child, and
     * links the two records through npe4__ReciprocalRelationship__c.
     * Creating the reciprocal explicitly here would therefore cause
     * duplicates, so it is deliberately left to NPSP.
     */
    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        // Normalise the input: ignore nulls and self-relationships, and
        // keep only the first occurrence of each unordered contact pair.
        Map<Id, Id> pairsByChildId = new Map<Id, Id>();
        Set<Id> allContactIds = new Set<Id>();
        Set<String> seenPairs = new Set<String>();

        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);

            if (childId == null || parentId == null || childId == parentId) {
                continue;
            }

            String childKey = String.valueOf(childId);
            String parentKey = String.valueOf(parentId);
            String pairKey = childKey.compareTo(parentKey) < 0
                ? childKey + '|' + parentKey
                : parentKey + '|' + childKey;

            if (!seenPairs.add(pairKey)) {
                continue;
            }

            pairsByChildId.put(childId, parentId);
            allContactIds.add(childId);
            allContactIds.add(parentId);
        }

        if (pairsByChildId.isEmpty()) {
            return;
        }

        // The single SOQL query: find every relationship already present
        // between any of the supplied contacts. Matching is then narrowed
        // to the exact requested pairs (in either direction) in Apex, so
        // unrelated relationships sharing only one contact do not cause
        // a pair to be skipped.
        Set<String> existingPairKeys = new Set<String>();
        for (npe4__Relationship__c existing : [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE npe4__Contact__c IN :allContactIds
              AND npe4__RelatedContact__c IN :allContactIds
        ]) {
            if (existing.npe4__Contact__c != null && existing.npe4__RelatedContact__c != null) {
                existingPairKeys.add(
                    String.valueOf(existing.npe4__Contact__c) + '|' +
                    String.valueOf(existing.npe4__RelatedContact__c)
                );
            }
        }

        List<npe4__Relationship__c> relationshipsToInsert = new List<npe4__Relationship__c>();

        for (Id childId : pairsByChildId.keySet()) {
            Id parentId = pairsByChildId.get(childId);

            String forwardKey = String.valueOf(childId) + '|' + String.valueOf(parentId);
            String reverseKey = String.valueOf(parentId) + '|' + String.valueOf(childId);

            // Re-running the import is safe: any existing relationship
            // between these two contacts, in either direction and of any
            // type or status, means the pair is skipped entirely.
            if (existingPairKeys.contains(forwardKey) || existingPairKeys.contains(reverseKey)) {
                continue;
            }

            relationshipsToInsert.add(new npe4__Relationship__c(
                npe4__Contact__c = childId,
                npe4__RelatedContact__c = parentId,
                npe4__Type__c = 'Parent',
                npe4__Status__c = 'Current'
            ));
        }

        // The single DML statement. NPSP creates and links each
        // reciprocal parent -> child (Son / Daughter / Child)
        // relationship from these records.
        if (!relationshipsToInsert.isEmpty()) {
            insert relationshipsToInsert;
        }
    }
}
