```apex
/**
 * @description TDTM handler that creates a follow-up Task for major gifts.
 *
 * Register via NPSP Settings > Trigger Configuration (Trigger Handler record):
 *   Active: true, Class: OPP_MajorGiftFollowUp_TDTM, Object: Opportunity,
 *   Trigger Action: AfterInsert;AfterUpdate, Load Order: 5, Asynchronous: false
 *
 * No Apex trigger is defined for this class. It only runs when NPSP's
 * TDTM dispatcher (the Opportunity TDTM trigger) invokes it, so it stops
 * running as soon as the admin deactivates the Trigger Handler record.
 *
 * A Task is created only when an Opportunity newly qualifies:
 * inserted as Closed Won with Amount >= 5000, or updated into that state
 * when it was not both Closed Won and >= 5000 before the update.
 */
global with sharing class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    private static final Decimal MAJOR_GIFT_THRESHOLD = 5000;
    private static final String CLOSED_WON_STAGE = 'Closed Won';
    private static final String TASK_SUBJECT = 'Major gift thank-you call';

    global override npsp.TDTM_Runnable.DmlWrapper run(
        List<SObject> newlist,
        List<SObject> oldlist,
        npsp.TDTM_Runnable.Action triggerAction,
        Schema.DescribeSObjectResult objResult
    ) {
        npsp.TDTM_Runnable.DmlWrapper dmlWrapper = new npsp.TDTM_Runnable.DmlWrapper();

        if (newlist == null || newlist.isEmpty()) {
            return dmlWrapper;
        }

        if (triggerAction != npsp.TDTM_Runnable.Action.AfterInsert &&
            triggerAction != npsp.TDTM_Runnable.Action.AfterUpdate) {
            return dmlWrapper;
        }

        // Index prior state by Id for AfterUpdate transition checks.
        // oldlist is null/empty on AfterInsert.
        Map<Id, Opportunity> oldOppById = new Map<Id, Opportunity>();
        if (oldlist != null) {
            for (SObject record : oldlist) {
                Opportunity oldOpp = (Opportunity) record;
                if (oldOpp.Id != null) {
                    oldOppById.put(oldOpp.Id, oldOpp);
                }
            }
        }

        for (SObject record : newlist) {
            Opportunity opp = (Opportunity) record;

            if (!isMajorClosedWon(opp)) {
                continue;
            }

            // Do not create another Task when editing a gift that
            // already qualified before this update.
            Opportunity oldOpp = oldOppById.get(opp.Id);
            if (oldOpp != null && isMajorClosedWon(oldOpp)) {
                continue;
            }

            dmlWrapper.objectsToInsert.add(new Task(
                Subject = TASK_SUBJECT,
                Priority = 'High',
                Status = 'Not Started',
                WhatId = opp.Id,
                WhoId = opp.npsp__Primary_Contact__c,
                OwnerId = opp.OwnerId,
                ActivityDate = opp.CloseDate != null ? opp.CloseDate.addDays(3) : null
            ));
        }

        // Return work to the TDTM dispatcher for DML: this handler performs
        // no SOQL and no DML of its own, so it is bulk-safe for 200 records.
        return dmlWrapper;
    }

    private static Boolean isMajorClosedWon(Opportunity opp) {
        return opp != null &&
            opp.StageName == CLOSED_WON_STAGE &&
            opp.Amount != null &&
            opp.Amount >= MAJOR_GIFT_THRESHOLD;
    }
}
