```apex
public with sharing class RecordAccessService {

    // Salesforce implementation restriction on UserRecordAccess:
    // a single SOQL query may contain at most 200 RecordId values.
    // Querying with more than 200 Ids throws a QueryException.
    private static final Integer MAX_RECORD_IDS_PER_QUERY = 200;

    /**
     * Returns the subset of recordIds that the running user can edit,
     * as reported by UserRecordAccess.HasEditAccess.
     *
     * This takes object permissions, ownership, sharing, role hierarchy,
     * View All / Modify All, etc. into account because UserRecordAccess
     * is computed by Salesforce from all of those mechanisms.
     *
     * Ids may belong to different objects; UserRecordAccess is
     * polymorphic over RecordId, so mixed-type Ids can be queried
     * together. Ids are chunked into batches of 200 to comply with
     * the UserRecordAccess query restriction, so 2,000 Ids use
     * 10 SOQL queries (within the 20-query budget).
     */
    public static Set<Id> editableIds(Set<Id> recordIds) {
        Set<Id> editable = new Set<Id>();

        if (recordIds == null || recordIds.isEmpty()) {
            return editable;
        }

        // Materialise to a list for chunking, dropping any null Ids
        // (a null in the IN bind could cause the query to fail and
        // can never be editable).
        List<Id> ids = new List<Id>();
        for (Id recordId : recordIds) {
            if (recordId != null) {
                ids.add(recordId);
            }
        }

        if (ids.isEmpty()) {
            return editable;
        }

        Id runningUserId = UserInfo.getUserId();

        for (Integer start = 0; start < ids.size(); start += MAX_RECORD_IDS_PER_QUERY) {
            Integer endExclusive = Math.min(start + MAX_RECORD_IDS_PER_QUERY, ids.size());

            // Apex Lists have no subList(), so build each chunk explicitly.
            List<Id> chunk = new List<Id>();
            for (Integer i = start; i < endExclusive; i++) {
                chunk.add(ids[i]);
            }

            // UserRecordAccess queries must be filtered by a single
            // UserId and by RecordId to be valid/efficient.
            for (UserRecordAccess access : [
                SELECT RecordId, HasEditAccess
                FROM UserRecordAccess
                WHERE UserId = :runningUserId
                  AND RecordId IN :chunk
            ]) {
                if (access.HasEditAccess == true) {
                    editable.add(access.RecordId);
                }
            }
        }

        return editable;
    }
}
