public with sharing class ContactImportService {
    public static void importContacts(List<Contact> contacts) {
        if (contacts == null || contacts.isEmpty()) {
            return;
        }

        // Bypass only this specific MetadataTriggerHandler action.
        // Do not bypass the Contact object (TriggerBase), flows
        // (TriggerActionFlow), or finalizers (FinalizerHandler), so
        // TA_Contact_FormatPhone and all other automation still run.
        MetadataTriggerHandler.bypass('TA_Contact_CreateWelcomeTask');
        try {
            insert contacts;
        } finally {
            // Always clear only this action's bypass, even if the
            // insert fails, so later inserts in this transaction
            // run TA_Contact_CreateWelcomeTask as usual.
            MetadataTriggerHandler.clearBypass('TA_Contact_CreateWelcomeTask');
        }
    }
}
