public with sharing class AccountOwnershipService {
    public static void reassign(Set<Id> accountIds, Id newOwnerId) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        List<Account> accounts = [
            SELECT Id, OwnerId
            FROM Account
            WHERE Id IN :accountIds
        ];
        List<Contact> contacts = [
            SELECT Id, OwnerId
            FROM Contact
            WHERE AccountId IN :accountIds
        ];

        for (Account account : accounts) {
            account.OwnerId = newOwnerId;
        }
        for (Contact contact : contacts) {
            contact.OwnerId = newOwnerId;
        }

        // Bypass all Account trigger actions (whole sObject) only for the
        // Account update. TriggerBase is the sObject-level bypass; using
        // MetadataTriggerHandler.bypass(String) would bypass a named action.
        TriggerBase.bypass(Schema.Account.SObjectType);
        try {
            if (!accounts.isEmpty()) {
                update accounts;
            }
        } finally {
            // Restore normal Account automation even if the DML throws;
            // the exception propagates unchanged (all-or-none DML).
            TriggerBase.clearBypass(Schema.Account.SObjectType);
        }

        // Account bypass is already cleared, so Contact actions (and any
        // Account automation they may indirectly invoke) run normally.
        if (!contacts.isEmpty()) {
            update contacts;
        }
    }
}
