public with sharing class TA_Opportunity_CollectForErpSync implements TriggerAction.AfterInsert, TriggerAction.AfterUpdate {
    private static Set<Id> collectedOpportunityIds = new Set<Id>();

    public void afterInsert(List<SObject> triggerNew) {
        for (SObject record : triggerNew) {
            Opportunity opportunityRecord = (Opportunity) record;
            if (opportunityRecord.Id != null) {
                collectedOpportunityIds.add(opportunityRecord.Id);
            }
        }
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Map<Id, Opportunity> oldById = new Map<Id, Opportunity>();
        for (SObject record : triggerOld) {
            Opportunity oldOpportunity = (Opportunity) record;
            oldById.put(oldOpportunity.Id, oldOpportunity);
        }

        for (SObject record : triggerNew) {
            Opportunity newOpportunity = (Opportunity) record;
            Opportunity oldOpportunity = oldById.get(newOpportunity.Id);
            if (
                newOpportunity.Id != null &&
                (oldOpportunity == null || newOpportunity.StageName != oldOpportunity.StageName)
            ) {
                collectedOpportunityIds.add(newOpportunity.Id);
            }
        }
    }

    public static Set<Id> drainCollectedOpportunityIds() {
        Set<Id> drainedIds = new Set<Id>(collectedOpportunityIds);
        collectedOpportunityIds.clear();
        return drainedIds;
    }
}
