public without sharing class TA_Contact_PreventDuplicateEmail implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {
    @TestVisible
    private static final String ERROR_MESSAGE = 'Another contact on this account already uses this email address.';

    public void beforeInsert(List<SObject> triggerNew) {
        List<Contact> contactsToCheck = new List<Contact>();
        for (SObject record : triggerNew) {
            contactsToCheck.add((Contact) record);
        }
        preventDuplicateEmails(contactsToCheck);
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Map<Id, Contact> oldMap = new Map<Id, Contact>();
        for (SObject record : triggerOld) {
            Contact oldContact = (Contact) record;
            oldMap.put(oldContact.Id, oldContact);
        }

        List<Contact> contactsToCheck = new List<Contact>();
        for (SObject record : triggerNew) {
            Contact newContact = (Contact) record;
            Contact oldContact = oldMap.get(newContact.Id);
            if (
                oldContact == null ||
                newContact.Email != oldContact.Email ||
                newContact.AccountId != oldContact.AccountId
            ) {
                contactsToCheck.add(newContact);
            }
        }
        preventDuplicateEmails(contactsToCheck);
    }

    private void preventDuplicateEmails(List<Contact> contacts) {
        List<Contact> candidates = new List<Contact>();
        Set<Id> accountIds = new Set<Id>();
        Set<Id> candidateIds = new Set<Id>();

        for (Contact candidate : contacts) {
            if (candidate.AccountId != null && String.isNotBlank(candidate.Email)) {
                candidates.add(candidate);
                accountIds.add(candidate.AccountId);
                if (candidate.Id != null) {
                    candidateIds.add(candidate.Id);
                }
            }
        }

        if (candidates.isEmpty()) {
            return;
        }

        Set<String> takenKeys = new Set<String>();
        // Single bulk query. Existing records for candidates themselves are
        // excluded so a contact never conflicts with itself on update; any
        // conflicts between records in this save are handled in order below.
        // Sharing is intentionally not applied (without sharing) so the
        // duplicate check sees every Contact on the relevant Accounts.
        for (Contact existing : [
            SELECT Id, AccountId, Email
            FROM Contact
            WHERE AccountId IN :accountIds AND Email != null
        ]) {
            if (!candidateIds.contains(existing.Id)) {
                takenKeys.add(buildKey(existing.AccountId, existing.Email));
            }
        }

        // Iterate in trigger order: the first occurrence is accepted and
        // reserves the key, each later duplicate in the same save is rejected.
        for (Contact candidate : candidates) {
            String key = buildKey(candidate.AccountId, candidate.Email);
            if (takenKeys.contains(key)) {
                candidate.addError(ERROR_MESSAGE);
            } else {
                takenKeys.add(key);
            }
        }
    }

    private String buildKey(Id accountId, String email) {
        return String.valueOf(accountId) + '|' + email.trim().toLowerCase();
    }
}
