/**
 * TriggerRecord implementation for Account, required by the Trigger Actions
 * Framework entry-criteria feature.
 *
 * MetadataTriggerHandler instantiates this class (no-arg constructor),
 * assigns `newSobject` / `oldSobject`, and then evaluates the entry-criteria
 * formula configured on Trigger_Action__mdt against it. The values are
 * therefore exposed as lazily-evaluated properties rather than fields
 * populated in the constructor: at construction time neither SObject has
 * been assigned yet.
 *
 * Both properties are null-safe. This setting/record type is shared by every
 * Account context, so it must not throw on insert or undelete (no old
 * record), on delete (no new record), or on any other update.
 */
global inherited sharing class AccountTriggerRecord extends TriggerRecord {
    private String ratingValue;
    private Boolean ratingValueSet = false;
    private String oldRatingValue;
    private Boolean oldRatingValueSet = false;

    global AccountTriggerRecord() {
    }

    global AccountTriggerRecord(SObject newRecord, SObject oldRecord) {
        this.newSobject = newRecord;
        this.oldSobject = oldRecord;
    }

    /** Rating on the new (trigger.new) version of the record. */
    global String Rating {
        get {
            if (ratingValueSet) {
                return ratingValue;
            }
            return newSobject == null
                ? null
                : (String) newSobject.get(Account.Rating);
        }
        set {
            ratingValue = value;
            ratingValueSet = true;
        }
    }

    /** Alias for Rating, for readability in entry-criteria formulae. */
    global String NewRating {
        get {
            return Rating;
        }
        set {
            Rating = value;
        }
    }

    /** Rating on the old (trigger.old) version of the record, null on insert. */
    global String OldRating {
        get {
            if (oldRatingValueSet) {
                return oldRatingValue;
            }
            return oldSobject == null
                ? null
                : (String) oldSobject.get(Account.Rating);
        }
        set {
            oldRatingValue = value;
            oldRatingValueSet = true;
        }
    }
}
