/**
 * Maintains Account.FB_Open_Case_Count__c as the number of open
 * (IsClosed = false) Cases for the Account.
 *
 * Runs in without sharing / system mode for the aggregate and the
 * Account update so the count reflects all Cases, not only those
 * visible to the running user, and can be maintained by users who
 * cannot edit the parent Account. Cases without an Account are ignored.
 * Bulk-safe: at most one aggregate SOQL and one DML per execution.
 */
public without sharing class TA_Case_RollupOpenCount
    implements
        TriggerAction.AfterInsert,
        TriggerAction.AfterUpdate,
        TriggerAction.AfterDelete,
        TriggerAction.AfterUndelete {

    public void afterInsert(List<SObject> triggerNew) {
        recalculate(accountIdsFrom(triggerNew));
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Set<Id> accountIds = new Set<Id>();
        for (Integer i = 0; i < triggerNew.size(); i++) {
            Case newCase = (Case) triggerNew[i];
            Case oldCase = (Case) triggerOld[i];
            // Only a change of parent or open/closed status can change a count.
            if (newCase.AccountId != oldCase.AccountId || newCase.IsClosed != oldCase.IsClosed) {
                if (newCase.AccountId != null) {
                    accountIds.add(newCase.AccountId);
                }
                if (oldCase.AccountId != null) {
                    accountIds.add(oldCase.AccountId);
                }
            }
        }
        recalculate(accountIds);
    }

    public void afterDelete(List<SObject> triggerOld) {
        recalculate(accountIdsFrom(triggerOld));
    }

    public void afterUndelete(List<SObject> triggerNew) {
        recalculate(accountIdsFrom(triggerNew));
    }

    private static Set<Id> accountIdsFrom(List<SObject> records) {
        Set<Id> accountIds = new Set<Id>();
        for (SObject record : records) {
            Case c = (Case) record;
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }
        return accountIds;
    }

    private static void recalculate(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        Map<Id, Integer> openCountByAccountId = new Map<Id, Integer>();
        for (AggregateResult result : [
            SELECT AccountId, COUNT(Id) openCount
            FROM Case
            WHERE AccountId IN :accountIds AND IsClosed = false
            GROUP BY AccountId
        ]) {
            openCountByAccountId.put(
                (Id) result.get('AccountId'),
                (Integer) result.get('openCount')
            );
        }

        List<Account> accountsToUpdate = new List<Account>();
        for (Id accountId : accountIds) {
            accountsToUpdate.add(
                new Account(
                    Id = accountId,
                    FB_Open_Case_Count__c = openCountByAccountId.containsKey(accountId)
                        ? openCountByAccountId.get(accountId)
                        : 0
                )
            );
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
