public with sharing class TA_Opportunity_LogAmountChange implements TriggerAction.AfterUpdate {
    private static final Set<Id> processedOpportunityIds = new Set<Id>();

    public void afterUpdate(List<Opportunity> triggerNew, List<Opportunity> triggerOld) {
        Map<Id, Opportunity> oldById = new Map<Id, Opportunity>(triggerOld);
        List<Task> tasksToInsert = new List<Task>();

        for (Opportunity opportunity : triggerNew) {
            // The rounding action performs a recursive update in the same
            // transaction. Only evaluate each opportunity on its first
            // after-update execution in that transaction.
            if (!processedOpportunityIds.add(opportunity.Id)) {
                continue;
            }

            Opportunity oldOpportunity = oldById.get(opportunity.Id);
            if (oldOpportunity != null && opportunity.Amount != oldOpportunity.Amount) {
                tasksToInsert.add(
                    new Task(
                        Subject = 'Amount changed',
                        WhatId = opportunity.Id,
                        Status = 'Completed'
                    )
                );
            }
        }

        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }
    }
}
