public inherited sharing class TA_Contact_Queries {
    public Map<Id, Account> accountsById = new Map<Id, Account>();

    private static TA_Contact_Queries instance;

    private TA_Contact_Queries() {
    }

    public static TA_Contact_Queries getInstance() {
        if (instance == null) {
            instance = new TA_Contact_Queries();
        }
        return instance;
    }

    public inherited sharing class Service implements TriggerAction.BeforeInsert {
        public void beforeInsert(List<SObject> triggerNew) {
            Set<Id> accountIds = new Set<Id>();
            for (SObject record : triggerNew) {
                Contact contactRecord = (Contact) record;
                if (contactRecord.AccountId != null) {
                    accountIds.add(contactRecord.AccountId);
                }
            }
            // Reload on every trigger execution so later DML in the same
            // transaction involving other accounts is not served stale data.
            // This is the single Account query shared by all Contact actions.
            TA_Contact_Queries.getInstance()
                .accountsById = new Map<Id, Account>(
                [
                    SELECT
                        Id,
                        BillingStreet,
                        BillingCity,
                        BillingPostalCode,
                        BillingCountry,
                        AccountSource
                    FROM Account
                    WHERE Id IN :accountIds
                ]
            );
        }
    }
}
